insert into public.legal_pages (slug, position, title, summary, sections) values
  ($lw$accessibility$lw$, 0, $lw$Accessibility Policy$lw$, $lw$This statement applies to the https://www.literaryworm.com website. LiteraryWorm is committed to ensuring our services are accessible to people with disabilities, so everyone at home can read and listen. We aim to conform with the Web Content Accessibility Guidelines (WCAG) 2.2 at Level AA.$lw$, $lw$[{"heading": "Accessibility features", "paragraphs": ["You should be able to change colors, contrast levels, and fonts; zoom in up to 200% without loss of information or functionality; navigate the website with just a keyboard, including keyboard shortcuts in the player; listen to the website using a screen reader, with labelled controls; use the read-along transcript with audiobooks; stop moving images with reduced motion; and turn on underlined links.", "The accessibility menu at the top of every page changes text size, theme (dark or light), an easier-to-read font, high contrast, underlined links and reduced motion. Your choices last for the visit.", "Every page works with a keyboard alone, and the player has keyboard shortcuts, listed under its controls. Buttons and links are at least 44 pixels square, focus is always visible, and dialogs keep focus inside them and return it when they close.", "Screen readers hear labelled controls, headings that outline each page, and announcements when something changes, such as a saved setting or a new club post. Pictures that carry meaning, like shared quote cards, have text alternatives; decorative covers are hidden from screen readers and their titles are always written nearby.", "In the reader you can choose the font, size, spacing, margins and theme. Audiobooks have speed control, a sleep timer, skip lengths you choose, and controls on your lock screen and headphones. The player's read-along transcript follows the narration."]}, {"heading": "Compatibility with assistive technology", "paragraphs": ["Our website is designed to be compatible with screen readers and other assistive technologies, using standard HTML and ARIA, in current versions of Chrome, Edge, Firefox and Safari. We haven't yet completed testing with each screen reader; if yours has trouble, please tell us."]}, {"heading": "Conformance status", "paragraphs": ["Status: partially conformant with WCAG 2.2 Level AA. Partially conformant means that most of the website conforms, with the exceptions listed under \"What we know isn't perfect yet\".", "We conducted our most recent accessibility evaluation in October 2026. For more information, see \"How we test\"."]}, {"heading": "What we know isn't perfect yet", "paragraphs": ["The read-along transcript for some titles is sample text rather than the exact recording, and is hidden while a real recording plays.", "Book details and covers from Google Books, and the LibriVox recordings, come from other services; we can't always fix problems in their content.", "Books you upload show their text only; images and tables in the original EPUB aren't shown."]}, {"heading": "How we test", "paragraphs": ["Every change is tested with a keyboard, at phone and desktop sizes, and with automated accessibility checks (Lighthouse accessibility scores of 100) before it's released."]}, {"heading": "Feedback and contact information", "paragraphs": ["Please let us know if you experience accessibility barriers using our services or need information in an alternative format. Tell us what you were trying to do, which page it was on, and the browser and assistive technology you use.", "Email: accessibility@literaryworm.com (mark the subject line \"Accessibility\").", "We aim to reply within five working days, and always within 15 business days, and to fix problems that block reading or listening first. We keep a record of accessibility feedback and our replies."]}, {"heading": "Enforcement", "paragraphs": ["If you're not satisfied with our response, you can contact the enforcement authority in your country: Germany: BFIT-Bund. France: Défenseur des droits. Ireland: National Disability Authority. Spain: OADIS. Italy: AgID. For other EU countries, contact your national consumer protection authority."]}, {"heading": "Preparation of this statement", "paragraphs": ["This statement was prepared on 28 October 2026 and is reviewed annually or when we make significant service changes.", "For questions about accessibility or this statement, email us at accessibility@literaryworm.com."]}]$lw$::jsonb),
  ($lw$privacy$lw$, 1, $lw$Privacy Policy$lw$, $lw$This Privacy Notice for LiteraryWorm ("we," "us," or "our") describes how and why we might access, collect, store, use, and/or share ("process") your personal information when you use our services ("Services"), including when you visit our website at https://www.literaryworm.com or any website of ours that links to this Privacy Notice, or engage with us in other related ways.$lw$, $lw$[{"heading": "Questions or concerns?", "paragraphs": ["Reading this Privacy Notice will help you understand your privacy rights and choices. We are responsible for making decisions about how your personal information is processed. If you do not agree with our policies and practices, please do not use our Services. If you still have any questions or concerns, please contact us at usprivacy@literaryworm.com."]}, {"heading": "Summary of key points", "paragraphs": ["This summary provides key points from our Privacy Notice; you can find out more details about any of these topics in the numbered sections below.", "What personal information do we process? When you visit, use, or navigate our Services, we may process personal information depending on how you interact with us and the Services, the choices you make, and the products and features you use. See section 1.", "Do we process any sensitive personal information? Some information may be considered \"special\" or \"sensitive\" in certain jurisdictions, for example your racial or ethnic origins, sexual orientation, religious beliefs, biometric or financial data. We don't collect any of those. The only information we hold that some laws treat as sensitive is your account login information.", "Do we collect any information from third parties? We do not collect any information from third parties.", "How do we process your information? We process your information to provide, improve, and administer our Services, communicate with you, for security and fraud prevention, and to comply with law. We may also process your information for other purposes with your consent. We process your information only when we have a valid legal reason to do so. See section 2.", "In what situations and with which parties do we share personal information? Only with the service providers that help us run LiteraryWorm, and in the specific situations described in section 4. We don't sell your personal information or share it for advertising.", "How do we keep your information safe? We have adequate organizational and technical processes and procedures in place to protect your personal information. However, no electronic transmission over the internet or information storage technology can be guaranteed to be 100% secure, so we cannot promise or guarantee that hackers, cybercriminals, or other unauthorized third parties will not be able to defeat our security and improperly collect, access, steal, or modify your information. See section 9.", "What are your rights? Depending on where you are located geographically, the applicable privacy law may mean you have certain rights regarding your personal information. See section 11.", "How do you exercise your rights? The easiest way is in Account, where you can download a copy of your data, change it, or delete it, or by contacting us at usprivacy@literaryworm.com. We will consider and act upon any request in accordance with applicable data protection laws."]}, {"heading": "1. What information do we collect?", "paragraphs": ["Personal information you disclose to us. In Short: We collect personal information that you provide to us.", "We collect personal information that you voluntarily provide to us when you register on the Services, when you participate in activities on the Services, or otherwise when you contact us.", "Personal Information Provided by You. The personal information that we collect depends on the context of your interactions with us and the Services, the choices you make, and the products and features you use. It includes your email address, display name, password, date of birth, contact preferences (marketing emails) and authentication data, and what you read, save and share in the app.", "Section 18 lists exactly what we keep.", "Sensitive Information. We do not collect biometric data, financial data, or other special categories of personal information.", "Payment Data. LiteraryWorm doesn't take payment yet, so we don't collect payment card numbers or billing addresses. If we add paid plans, payment data will be handled and stored by Stripe (https://stripe.com/privacy), and we'll update this notice before we do.", "Social Media Login Data. We don't offer registration or log in with social media accounts.", "All personal information that you provide to us must be true, complete, and accurate, and you must notify us of any changes to such personal information.", "Information automatically collected. In Short: Some information — such as your Internet Protocol (IP) address and browser and device characteristics — is collected automatically when you visit our Services.", "Log and Usage Data. Our hosting and backend providers (Vercel and Supabase) automatically record service-related, diagnostic and performance information when you access the Services, in log files. This may include your IP address, browser type, the date and time of requests, the pages and files requested, and error reports. It is used to keep the Services secure and working, not for advertising, and we don't build profiles from it.", "Location Data. We don't collect your device's location, and we don't use GPS or similar technologies.", "Google API. We use the Google Books API only for book information: our server sends it search words and book ids, never who's asking. Our use of information received from Google APIs will adhere to Google API Services User Data Policy, including the Limited Use requirements."]}, {"heading": "2. How do we process your information?", "paragraphs": ["In Short: We process your information to provide, improve, and administer our Services, communicate with you, for security and fraud prevention, and to comply with law. We may also process your information for other purposes only with your prior explicit consent.", "To facilitate account creation and authentication and otherwise manage user accounts. We may process your information so you can create and log in to your account, as well as keep your account and household profiles in working order.", "To deliver and facilitate delivery of services to the user. We may process your information to provide you with the requested service, such as keeping your place in a book across devices, your bookmarks, highlights, lists, goals and stats.", "To respond to user inquiries/offer support to users. We may process your information to respond to your inquiries and solve any potential issues you might have with the requested service.", "To send administrative information to you. We may process your information to send you details about your account, changes to our terms and policies, and other similar information.", "To enable user-to-user communications. We may process your information if you choose to use any of our offerings that allow for communication with another user, such as reading logs, book clubs and shared lists.", "To send you marketing and promotional communications, only if you turned on marketing emails. You can turn them off at any time in Account. For more information, see section 11.", "To show you recommendations. Book recommendations and reading stats are worked out in your browser from your own reading; they aren't used for advertising.", "To protect our Services. We may process your information as part of our efforts to keep our Services safe and secure, including fraud monitoring and prevention and limiting how often our features can be used.", "To save or protect an individual's vital interest. We may process your information when necessary to save or protect an individual's vital interest, such as to prevent harm.", "We don't process your information to deliver targeted advertising."]}, {"heading": "3. What legal bases do we rely on to process your information?", "paragraphs": ["In Short: We only process your personal information when we believe it is necessary and we have a valid legal reason (i.e., legal basis) to do so under applicable law, like with your consent, to comply with laws, to provide you with services to enter into or fulfill our contractual obligations, to protect your rights, or to fulfill our legitimate business interests.", "If you are located in the EU or UK, this section applies to you. The General Data Protection Regulation (GDPR) and UK GDPR require us to explain the valid legal bases we rely on in order to process your personal information. As such, we may rely on the following legal bases to process your personal information:", "Consent. We may process your information if you have given us permission (i.e., consent) to use your personal information for a specific purpose, such as marketing emails or a Kids profile. You can withdraw your consent at any time (see section 11).", "Performance of a Contract. We may process your personal information when we believe it is necessary to fulfill our contractual obligations to you, including providing our Services or at your request prior to entering into a contract with you.", "Legitimate Interests. We may process your information when we believe it is reasonably necessary to achieve our legitimate business interests and those interests do not outweigh your interests and fundamental rights and freedoms: to diagnose problems and prevent fraudulent activities, and to keep the Services secure and working.", "Legal Obligations. We may process your information where we believe it is necessary for compliance with our legal obligations, such as to cooperate with a law enforcement body or regulatory agency, exercise or defend our legal rights, or disclose your information as evidence in litigation in which we are involved.", "Vital Interests. We may process your information where we believe it is necessary to protect your vital interests or the vital interests of a third party, such as situations involving potential threats to the safety of any person.", "If you are located in Canada, this section applies to you. We may process your information if you have given us specific permission (i.e., express consent) to use your personal information for a specific purpose, or in situations where your permission can be inferred (i.e., implied consent). You can withdraw your consent at any time.", "In some exceptional cases, we may be legally permitted under applicable law to process your information without your consent, including, for example: if collection is clearly in the interests of an individual and consent cannot be obtained in a timely way; for investigations and fraud detection and prevention; for business transactions provided certain conditions are met; if it is contained in a witness statement and the collection is necessary to assess, process, or settle an insurance claim; for identifying injured, ill, or deceased persons and communicating with next of kin; if we have reasonable grounds to believe an individual has been, is, or may be victim of financial abuse; if it is reasonable to expect collection and use with consent would compromise the availability or the accuracy of the information and the collection is reasonable for purposes related to investigating a breach of an agreement or a contravention of the laws of Canada or a province; if disclosure is required to comply with a subpoena, warrant, court order, or rules of the court relating to the production of records; if it was produced by an individual in the course of their employment, business, or profession and the collection is consistent with the purposes for which the information was produced; if the collection is solely for journalistic, artistic, or literary purposes; and if the information is publicly available and is specified by the regulations. We may disclose de-identified information for approved research or statistics projects, subject to ethics oversight and confidentiality commitments."]}, {"heading": "4. When and with whom do we share your personal information?", "paragraphs": ["In Short: We share information only with the service providers that help us run LiteraryWorm, and in the situations described in this section.", "Service providers. Supabase stores the data above and runs our server functions. Vercel hosts the website. Neither may use your data for their own purposes.", "Anthropic (Claude) writes book summaries and answers Ask the book questions (see section 6).", "Google Books answers searches and book details through our server, which sends only the search words and book ids, never who's asking. LibriVox recordings stream from the Internet Archive, and fonts load from Google Fonts, directly from your browser.", "Other members. Reading logs are public, with your display name. Book club posts are seen by the club's members. Lists you share can be read by anyone with the link. Staff with the right access can see account details to run the service and help you.", "Business Transfers. We may share or transfer your information in connection with, or during negotiations of, any merger, sale of company assets, financing, or acquisition of all or a portion of our business to another company."]}, {"heading": "5. Do we use cookies and other tracking technologies?", "paragraphs": ["In Short: We use only essential cookies and similar technologies, described in our Cookie Policy.", "The technologies we use help us maintain the security of our Services and your account, keep you signed in, and let the app work offline.", "We don't permit third parties or service providers to use online tracking technologies on our Services for analytics or advertising, and we don't use Google Analytics or any other analytics or advertising service.", "Specific information about the technologies we use and how you can refuse certain cookies is set out in our Cookie Policy."]}, {"heading": "6. Do we offer artificial intelligence-based products?", "paragraphs": ["In Short: We offer products, features, or tools powered by artificial intelligence, machine learning, or similar technologies.", "As part of our Services, we offer features powered by artificial intelligence (\"AI Products\"). The terms in this Privacy Notice govern your use of the AI Products within our Services.", "Use of AI Technologies. We provide the AI Products through one third-party service provider (\"AI Service Provider\"): Anthropic (Claude). We don't use OpenAI, Hugging Face, Google Cloud AI, DeepSeek or Gemini to process your information. Figma Make was used only to design the app's screens and never receives your information. You must not use the AI Products in any way that violates the terms or policies of the AI Service Provider.", "Our AI Products. Book summaries: short and detailed summaries of books in our catalog, written the first time anyone asks, from the book's details; no personal information is sent. Ask the book: answers to your questions about a public-domain book. We send your question and the book's text up to your chapter; we don't send your name, email or account details. Ask the book isn't offered to Kids profiles. Summaries and answers are labelled as written by AI.", "How We Process Your Data Using AI. All personal information processed using our AI Products is handled in line with this Privacy Notice and our agreement with the AI Service Provider. We don't use your reading history, notes, uploads or posts to train AI models."]}, {"heading": "7. How do we handle your social logins?", "paragraphs": ["We don't offer registration or log in using social media accounts. If we add it, we'll update this Privacy Notice first."]}, {"heading": "8. How long do we keep your information?", "paragraphs": ["In Short: We keep your information for as long as necessary to fulfill the purposes outlined in this Privacy Notice unless otherwise required by law.", "We will only keep your personal information for as long as it is necessary for the purposes set out in this Privacy Notice, unless a longer retention period is required or permitted by law (such as tax, accounting, or other legal requirements). No purpose in this notice will require us keeping your personal information for longer than the period of time in which users have an account with us.", "When we have no ongoing legitimate business need to process your personal information, we will either delete or anonymize such information, or, if this is not possible (for example, because your personal information has been stored in backup archives), then we will securely store your personal information and isolate it from any further processing until deletion is possible."]}, {"heading": "9. How do we keep your information safe?", "paragraphs": ["In Short: We aim to protect your personal information through a system of organizational and technical security measures.", "We have implemented appropriate and reasonable technical and organizational security measures designed to protect the security of any personal information we process. For example, connections use HTTPS, and access rules in our database let each account read only its own data. However, despite our safeguards and efforts to secure your information, no electronic transmission over the Internet or information storage technology can be guaranteed to be 100% secure, so we cannot promise or guarantee that hackers, cybercriminals, or other unauthorized third parties will not be able to defeat our security and improperly collect, access, steal, or modify your information. Although we will do our best to protect your personal information, transmission of personal information to and from our Services is at your own risk. You should only access the Services within a secure environment."]}, {"heading": "10. Do we collect information from minors?", "paragraphs": ["In Short: We do not knowingly collect data from or market to children under 18 years of age or the equivalent age as specified by law in your jurisdiction, except through Kids profiles that a parent or guardian creates on their own account.", "Account holders must be 18 or older. We do not knowingly collect, solicit data from, or market to children under 18 years of age or the equivalent age as specified by law in your jurisdiction, nor do we knowingly sell such personal information. By using the Services, you represent that you are at least 18 or the equivalent age as specified by law in your jurisdiction or that you are the parent or guardian of such a minor and consent to such minor dependent's use of the Services through a Kids profile. The Children's Privacy Notice explains what Kids profiles keep.", "If we learn that personal information from users less than 18 years of age or the equivalent age as specified by law in your jurisdiction has been collected without that consent, we will deactivate the account and take reasonable measures to promptly delete such data from our records. If you become aware of any such data, please contact us at usprivacy@literaryworm.com."]}, {"heading": "11. What are your privacy rights?", "paragraphs": ["In Short: Depending on your state of residence in the US or in some regions, such as the European Economic Area (EEA), United Kingdom (UK), Switzerland, and Canada, you have rights that allow you greater access to and control over your personal information. You may review, change, or terminate your account at any time, depending on your country, province, or state of residence.", "In some regions (like the EEA, UK, Switzerland, and Canada), you have certain rights under applicable data protection laws. These may include the right (i) to request access and obtain a copy of your personal information, (ii) to request rectification or erasure; (iii) to restrict the processing of your personal information; (iv) if applicable, to data portability; and (v) not to be subject to automated decision-making. If a decision that produces legal or similarly significant effects is made solely by automated means, we will inform you, explain the main factors, and offer a simple way to request human review. In certain circumstances, you may also have the right to object to the processing of your personal information. You can make such a request by contacting us by using the contact details provided in the section \"20. How can you contact us about this notice?\" below.", "We will consider and act upon any request in accordance with applicable data protection laws.", "If you are located in the UK and are unhappy with how we have handled your personal information, you can make a complaint directly to us at usprivacy@literaryworm.com. This is in addition to the rights you have under the UK General Data Protection Regulation and the Data Protection Act 2018.", "What happens after you complain: we will acknowledge your complaint within 30 days of receiving it, investigate without unjustifiable or excessive delay, keep you informed of progress and explain the outcome.", "If you are not happy with our final response, you can refer your complaint to the Information Commissioner's Office, the UK supervisory authority. Website: ico.org.uk/make-a-complaint. Helpline: 0303 123 1113. Post: Information Commissioner's Office, Wycliffe House, Water Lane, Wilmslow, Cheshire, SK9 5AF.", "If you are located in the EEA or UK and you believe we are unlawfully processing your personal information, you also have the right to complain to your Member State data protection authority or UK data protection authority.", "If you are located in Switzerland, you may contact the Federal Data Protection and Information Commissioner.", "Withdrawing your consent: If we are relying on your consent to process your personal information, which may be express and/or implied consent depending on the applicable law, you have the right to withdraw your consent at any time. You can withdraw your consent at any time in Account (for marketing emails and Kids profiles) or by contacting us by using the contact details provided in the section \"20. How can you contact us about this notice?\" below.", "However, please note that this will not affect the lawfulness of the processing before its withdrawal nor, when applicable law allows, will it affect the processing of your personal information conducted in reliance on lawful processing grounds other than consent.", "Opting out of marketing and promotional communications: You can unsubscribe from our marketing and promotional communications at any time by turning off marketing emails in Account, by clicking on the unsubscribe link in the emails that we send, or by contacting us. We may still communicate with you, for example to send you service-related messages that are necessary for the administration and use of your account, to respond to service requests, or for other non-marketing purposes.", "Account Information. If you would at any time like to review or change the information in your account or terminate your account, you can log in and go to Account. There you can change your details, download a copy of your data, and delete profiles or your whole account. Deleting your account deletes its information from our databases straight away; copies in our providers' backups are removed when those backups expire.", "Cookies and similar technologies: Most Web browsers are set to accept cookies by default. If you prefer, you can usually choose to set your browser to remove cookies and to reject cookies. If you choose to remove cookies or reject cookies, this could affect certain features or services of our Services.", "If you have questions or comments about your privacy rights, you may email us at usprivacy@literaryworm.com."]}, {"heading": "12. Controls for Do-Not-Track features", "paragraphs": ["Most web browsers and some mobile operating systems and mobile applications include a Do-Not-Track (\"DNT\") feature or setting you can activate to signal your privacy preference not to have data about your online browsing activities monitored and collected. At this stage, no uniform technology standard for recognizing and implementing DNT signals has been finalized. As such, we do not currently respond to DNT browser signals or any other mechanism that automatically communicates your choice not to be tracked online. We don't track you across other websites in any case. If a standard for online tracking is adopted that we must follow in the future, we will inform you about that practice in a revised version of this Privacy Notice.", "California law requires us to let you know how we respond to web browser DNT signals. Because there currently is not an industry or legal standard for recognizing or honoring DNT signals, we do not respond to them at this time.", "Global Privacy Control: We recognize and honor Global Privacy Control (GPC) signals. If you use a browser or extension that supports GPC, we will treat this as a valid request to opt out of the sale or sharing of your personal information for targeted advertising purposes under applicable state privacy laws, including the California Consumer Privacy Act (CCPA). We don't sell or share personal information, so nothing more needs to change for you. For more information about GPC and how to enable it, visit globalprivacycontrol.org."]}, {"heading": "13. Do United States residents have specific privacy rights?", "paragraphs": ["In Short: If you are a resident of California, Colorado, Connecticut, Delaware, Florida, Indiana, Iowa, Kentucky, Maryland, Minnesota, Montana, Nebraska, New Hampshire, New Jersey, Oregon, Rhode Island, Tennessee, Texas, Utah, or Virginia, you may have the right to request access to and receive details about the personal information we maintain about you and how we have processed it, correct inaccuracies, get a copy of, or delete your personal information. You may also have the right to withdraw your consent to our processing of your personal information. These rights may be limited in some circumstances by applicable law. More information is provided below.", "Categories of Personal Information We Collect. These are the categories of personal information we have collected in the past twelve (12) months. For a full list of what we process, see sections 1 and 18.", "A. Identifiers (such as name, alias, online identifier, Internet Protocol address, email address, and account name): YES. Your email address, display name, account id, and IP address in our providers' logs.", "B. Personal information as defined in the California Customer Records statute (name, contact information, education, employment, employment history, and financial information): YES, your display name and email address only.", "C. Protected classification characteristics under state or federal law (gender, age, date of birth, race and ethnicity, national origin, marital status, and other demographic data): YES, your date of birth only, to confirm you're 18 or over.", "D. Commercial information (transaction information, purchase history, financial details, and payment information): NO. We record which plan you chose, but we take no payment.", "E. Biometric information (fingerprints and voiceprints): NO.", "F. Internet or other similar network activity (browsing history, search history, online behavior, interest data, and interactions with our and other websites, applications, systems, and advertisements): YES, within LiteraryWorm only: your searches and reading activity on our Services. Not your activity on other websites.", "G. Geolocation data (device location): NO.", "H. Audio, electronic, sensory, or similar information (images and audio, video or call recordings): NO.", "I. Professional or employment-related information: NO.", "J. Education Information (student records and directory information): NO.", "K. Inferences drawn from collected personal information (a profile or summary of an individual's preferences and characteristics): YES. Book recommendations, worked out in your browser from your own reading and not used for advertising.", "L. Sensitive personal information: YES, account login information only. No biometric data.", "We will use and retain the personal information in each category for as long as the user has an account with us.", "We only collect sensitive personal information, as defined by applicable privacy laws or the purposes allowed by law or with your consent. Sensitive personal information may be used, or disclosed to a service provider or contractor, for additional, specified purposes. You may have the right to limit the use or disclosure of your sensitive personal information. We do not collect or process sensitive personal information for the purpose of inferring characteristics about you.", "We may also collect other personal information outside of these categories when you receive help through our customer support channels, or to deliver our Services and respond to your inquiries.", "Sources of Personal Information. See section 1. How We Use and Share Personal Information. See sections 2 and 4.", "Will your information be shared with anyone else? We may disclose your personal information with our service providers pursuant to a written contract between us and each service provider. See section 4. We may use your personal information for our own business purposes, such as for undertaking internal research for technological development and demonstration. This is not considered to be \"selling\" of your personal information.", "We have not disclosed, sold, or shared any personal information to third parties for a business or commercial purpose in the preceding twelve (12) months. We will not sell or share personal information in the future belonging to website visitors, users, and other consumers.", "Your Rights. You have rights under certain US state data protection laws. However, these rights are not absolute, and in certain cases, we may decline your request as permitted by law. These rights include: the right to know whether or not we are processing your personal data; to access your personal data; to correct inaccuracies in your personal data; to request the deletion of your personal data; to obtain a copy of the personal data you previously shared with us; to non-discrimination for exercising your rights; and to opt out of the processing of your personal data if it is used for targeted advertising (or sharing as defined under California's privacy law), the sale of personal data, or profiling in furtherance of decisions that produce legal or similarly significant effects (\"profiling\").", "Depending upon the state where you live, you may also have the right to access the categories of personal data being processed (including in Minnesota); to obtain a list of the categories of third parties to which we have disclosed personal data (including in California, Delaware, and Maryland); to obtain a list of specific third parties to which we have disclosed personal data (including in Minnesota and Oregon); to obtain a list of third parties to which we have sold personal data (including in Connecticut); to review, understand, question, and depending on where you live, correct how personal data has been profiled (including in Connecticut and Minnesota); to limit use and disclosure of sensitive personal data (including in California); and to opt out of the collection of sensitive data and personal data collected through the operation of a voice or facial recognition feature (including in Florida).", "How to Exercise Your Rights. To exercise these rights, you can use Account (to download, change or delete your data), email us at usprivacy@literaryworm.com, or use the contact details at the bottom of this document. We will honor your opt-out preferences if you enact the Global Privacy Control (GPC) opt-out signal on your browser.", "Under certain US state data protection laws, you can designate an authorized agent to make a request on your behalf. We may deny a request from an authorized agent that does not submit proof that they have been validly authorized to act on your behalf in accordance with applicable laws.", "Request Verification. Upon receiving your request, we will need to verify your identity to determine you are the same person about whom we have the information in our system. We will only use personal information provided in your request to verify your identity or authority to make the request. However, if we cannot verify your identity from the information already maintained by us, we may request that you provide additional information for the purposes of verifying your identity and for security or fraud-prevention purposes.", "If you submit the request through an authorized agent, we may need to collect additional information to verify your identity before processing your request and the agent will need to provide a written and signed permission from you to submit such request on your behalf.", "Appeals. Under certain US state data protection laws, if we decline to take action regarding your request, you may appeal our decision by emailing us at usprivacy@literaryworm.com. We will inform you in writing of any action taken or not taken in response to the appeal, including a written explanation of the reasons for the decisions. If your appeal is denied, you may submit a complaint to your state attorney general.", "California \"Shine The Light\" Law. California Civil Code Section 1798.83, also known as the \"Shine The Light\" law, permits our users who are California residents to request and obtain from us, once a year and free of charge, information about categories of personal information (if any) we disclosed to third parties for direct marketing purposes and the names and addresses of all third parties with which we shared personal information in the immediately preceding calendar year. We don't disclose personal information to third parties for their direct marketing. If you are a California resident and would like to make such a request, please submit your request in writing to us by using the contact details provided in the section \"20. How can you contact us about this notice?\" below."]}, {"heading": "14. Do other regions have specific privacy rights?", "paragraphs": ["In Short: You may have additional rights based on the country you reside in.", "Australia and New Zealand. We collect and process your personal information under the obligations and conditions set by Australia's Privacy Act 1988 and New Zealand's Privacy Act 2020 (Privacy Act).", "This Privacy Notice satisfies the notice requirements defined in both Privacy Acts, in particular: what personal information we collect from you, from which sources, for which purposes, and other recipients of your personal information.", "If you do not wish to provide the personal information necessary to fulfill their applicable purpose, it may affect our ability to provide our services, in particular to offer you the products or services that you want, respond to or help with your requests, manage your account with us, and confirm your identity and protect your account.", "At any time, you have the right to request access to or correction of your personal information. You can make such a request by contacting us by using the contact details provided in section 21.", "If you believe we are unlawfully processing your personal information, you have the right to submit a complaint about a breach of the Australian Privacy Principles to the Office of the Australian Information Commissioner and a breach of New Zealand's Privacy Principles to the Office of New Zealand Privacy Commissioner.", "Republic of South Africa. At any time, you have the right to request access to or correction of your personal information. You can make such a request by contacting us by using the contact details provided in section 21.", "If you are unsatisfied with the manner in which we address any complaint with regard to our processing of personal information, you can contact the office of the regulator, the Information Regulator (South Africa). General enquiries: enquiries@inforegulator.org.za. Complaints (complete POPIA/PAIA form 5): PAIAComplaints@inforegulator.org.za and POPIAComplaints@inforegulator.org.za."]}, {"heading": "15. Licensing and selling your information", "paragraphs": ["We don't sell, rent or license your personal information, and we don't share it for advertising. We use it only to run LiteraryWorm for you.", "Content you post (reading logs and club posts) stays yours. The Terms of Service explain the limited licence you give us to show it where you posted it.", "We don't use your reading history, notes, uploads or posts to train AI models."]}, {"heading": "16. How long we keep it", "paragraphs": ["We keep your data while your account is open. Deleting a profile deletes its data, including its uploaded books. Deleting your account deletes everything at once, including your uploads; public logs and club posts go with it.", "To protect the service from abuse, we keep short-lived counts of requests, keyed by a one-way hash of your account or network address, and clear them within a day."]}, {"heading": "17. Your choices and rights", "paragraphs": ["In Account you can download a copy of your data, change your display name and marketing emails, and delete profiles or your whole account. You can remove any log, post, highlight or upload yourself.", "We honour Global Privacy Control. Children's data is covered by the Children's Privacy Notice, and what we keep in your browser by the Cookie Policy."]}, {"heading": "18. What we collect", "paragraphs": ["Your account: your email address, display name, password, date of birth (to confirm you're 18 or over), whether you'd like marketing emails, when you accepted the Terms, and your plan. Your password is handled by our sign-in provider and kept only as a one-way hash; we never see it.", "Your household: each profile's name, avatar, age rating, favourite genres, daily limit and player settings. A profile PIN is kept only as a one-way hash. For Kids profiles, we keep a record of the parent's consent.", "Your reading: your library, reading progress, bookmarks, highlights and notes, ratings, favourites and lists, recent searches, reading goals, time read and listened each day, and the books you finish.", "Things you share or add: reading logs (public, with your display name), book club posts (seen by the club's members), lists you choose to share by link, and books you upload (private to the profile that added them; we keep their text only).", "Devices: while you're signed in, a short label for each open copy of the app (such as \"Chrome on Windows\") so you can send a book to another device."]}, {"heading": "19. Do we make updates to this notice?", "paragraphs": ["In Short: Yes, we will update this notice as necessary to stay compliant with relevant laws.", "We may update this Privacy Notice from time to time. The updated version will be indicated by an updated \"Last updated\" date at the top of this Privacy Notice. If we make material changes to this Privacy Notice, we may notify you either by prominently posting a notice of such changes or by directly sending you a notification. We encourage you to review this Privacy Notice frequently to be informed of how we are protecting your information."]}, {"heading": "20. How can you contact us about this notice?", "paragraphs": ["If you have questions or comments about this notice, you may email us at usprivacy@literaryworm.com."]}, {"heading": "21. How can you review, update, or delete the data we collect from you?", "paragraphs": ["Based on the applicable laws of your country or state of residence in the US, you may have the right to request access to the personal information we collect from you, details about how we have processed it, correct inaccuracies, or delete your personal information. You may also have the right to withdraw your consent to our processing of your personal information. These rights may be limited in some circumstances by applicable law.", "To review, update, or delete your personal information, go to Account, where you can download a copy of your data, change it, or delete it, or email us at usprivacy@literaryworm.com."]}]$lw$::jsonb),
  ($lw$cookies$lw$, 2, $lw$Cookie Policy$lw$, $lw$This Cookie Policy explains how LiteraryWorm ("Company," "we," "us," and "our") uses cookies and similar technologies to recognize you when you visit our website at https://www.literaryworm.com ("Website"). It explains what these technologies are and why we use them, as well as your rights to control our use of them.$lw$, $lw$[{"heading": "About this policy", "paragraphs": ["In some cases we may use cookies to collect personal information, or that becomes personal information if we combine it with other information."]}, {"heading": "What are cookies?", "paragraphs": ["Cookies are small data files that are placed on your computer or mobile device when you visit a website. Cookies are widely used by website owners in order to make their websites work, or to work more efficiently, as well as to provide reporting information.", "Cookies set by the website owner (in this case, LiteraryWorm) are called \"first-party cookies.\" Cookies set by parties other than the website owner are called \"third-party cookies.\" Third-party cookies enable third-party features or functionality to be provided on or through the website (e.g., advertising, interactive content, and analytics). The parties that set these third-party cookies can recognize your computer both when it visits the website in question and also when it visits certain other websites."]}, {"heading": "Why do we use cookies?", "paragraphs": ["Some cookies are required for technical reasons in order for our Website to operate, and we refer to these as \"essential\" or \"strictly necessary\" cookies. LiteraryWorm uses only essential cookies and similar technologies. We don't use cookies to track or target your interests, and we don't let third parties serve cookies through our Website for advertising or analytics. This is described in more detail below."]}, {"heading": "How can I control cookies?", "paragraphs": ["You have the right to decide whether to accept or reject cookies. Essential cookies cannot be rejected as they are strictly necessary to provide you with services.", "Because we use only essential cookies, there is no cookie notification banner or Cookie Preference Center at the moment. If we ever add cookies that aren't essential, we'll ask for your choice first, in a Cookie Preference Center, and update this page.", "You may also set or amend your web browser controls to accept or refuse cookies. If you choose to reject cookies, you may still use our Website though your access to some functionality and areas of our Website may be restricted.", "The specific types of first- and third-party cookies served through our Website and the purposes they perform are described below (please note that the specific cookies served may vary depending on the specific Online Properties you visit)."]}, {"heading": "Essential website cookies", "paragraphs": ["These cookies are strictly necessary to provide you with services available through our Website and to use some of its features, such as access to secure areas.", "__cf_bm. Purpose: Cloudflare places the cookie on end-user devices that access customer sites protected by Bot Management or Bot Fight Mode. Provider: .supabase.co (our backend, Supabase, which is protected by Cloudflare). Service: Cloudflare (see Cloudflare's privacy policy). Type: server cookie. Expires in: 30 minutes.", "Some book covers from Google Books, and the audiobook recordings streamed from the Internet Archive, load from those services. When your browser fetches them, those services may set or read their own cookies under their own policies. Blocking third-party cookies in your browser doesn't stop LiteraryWorm working."]}, {"heading": "Similar technologies: what we keep in your browser", "paragraphs": ["Signed in: when you log in, your browser keeps your sign-in session (in local storage, under literaryworm-session) so you stay signed in after a refresh. It's strictly necessary for your account to work, and it's removed when you log out.", "The app itself: so LiteraryWorm opens quickly and without a connection, your browser keeps a copy of the app's own files (its pages, code, icons and app manifest). This holds nothing about you.", "Books you save for offline: when you choose Read offline, the book's text, and its audio if you ask, are kept on your device until you remove them from the book's page.", "Books you upload: once you've opened one, its text is kept on that device so it keeps working if your connection drops. It's removed when you delete the book or log out.", "Everything else, such as reader settings, playback speed, the demo household and uploads made in the demo, stays in the open tab only and is gone when you refresh or close it.", "Your library, reading progress, bookmarks, highlights, lists, ratings, reading time, player settings, club activity and uploaded books are saved with your account on our servers (Supabase), not in browser cookies. The Privacy Policy says how we use them, and Account lets you download or delete them."]}, {"heading": "Do my choices apply on all my devices?", "paragraphs": ["No. Cookie settings you make in your browser, and anything you clear there, apply to that browser on that device only. You'll need to make them again on a different device or browser, and a private or incognito window deletes what it kept when you close it.", "Clearing LiteraryWorm's site data signs you out, and books saved for offline will need saving again."]}, {"heading": "How can I control cookies on my browser?", "paragraphs": ["As the means by which you can refuse cookies through your web browser controls vary from browser to browser, you should visit your browser's help menu for more information. This applies to the most popular browsers: Chrome, Internet Explorer, Firefox, Safari, Edge and Opera.", "In addition, most advertising networks offer you a way to opt out of targeted advertising. If you would like to find out more information, please visit the Digital Advertising Alliance, the Digital Advertising Alliance of Canada or the European Interactive Digital Advertising Alliance."]}, {"heading": "What about other tracking technologies, like web beacons?", "paragraphs": ["Cookies are not the only way to recognize or track visitors to a website. Web beacons (sometimes called \"tracking pixels\" or \"clear gifs\") are tiny graphics files that contain a unique identifier that lets a website recognize when someone has visited it or opened an email including them.", "LiteraryWorm doesn't use web beacons or tracking pixels on the Website or in its emails."]}, {"heading": "Do you serve targeted advertising?", "paragraphs": ["No. We don't serve advertising on our Website, and we don't allow third parties to place cookies or web beacons on your computer or mobile device through our Website to serve or measure advertising."]}, {"heading": "How often will you update this Cookie Policy?", "paragraphs": ["We may update this Cookie Policy from time to time in order to reflect, for example, changes to the cookies we use or for other operational, legal, or regulatory reasons. Please therefore revisit this Cookie Policy regularly to stay informed about our use of cookies and related technologies.", "The date at the top of this Cookie Policy indicates when it was last updated."]}, {"heading": "Where can I get further information?", "paragraphs": ["If you have any questions about our use of cookies or other technologies, please email us at support@literaryworm.com."]}]$lw$::jsonb),
  ($lw$childrens-privacy$lw$, 3, $lw$Children's Privacy Notice$lw$, $lw$For parents and guardians: what a Kids profile collects, why, who can see it, and how you stay in control. Kids profiles collect only what the service needs, and only after you consent.$lw$, $lw$[{"heading": "Your consent comes first", "paragraphs": ["Only the account holder, who must be 18 or older, can create a Kids profile or move a profile to Kids, and only after reading this notice and confirming with the account password. We keep a record of that consent: when it was given, how, and which version of this notice it was for."]}, {"heading": "What a Kids profile collects", "paragraphs": ["The profile's first name or nickname and avatar, its age rating and any daily reading limit you set, and its reading: the books in its library, where it is in each book, bookmarks, highlights and notes, ratings, favourites and lists, reading time and goals.", "We don't ask a child for their email, full name, address, photo, location or any other contact details."]}, {"heading": "What a Kids profile can't do", "paragraphs": ["Kids profiles see only books rated for children. They can't write public reading logs, join or start book clubs, share lists by link, upload books, ask the book's AI assistant, make purchases or change account settings. A grown-up's password is needed to open Account or to allow extra time past a daily limit."]}, {"heading": "Who sees it", "paragraphs": ["A Kids profile's reading is private to your account. It isn't shown to other members, isn't used for advertising, and is never sold, rented or licensed. Our hosting providers (Supabase and Vercel) store it only to run LiteraryWorm for you."]}, {"heading": "Your choices as a parent", "paragraphs": ["From Account you can see and download the profile's data, change its limits, add a PIN to other profiles so a child can't open them, move the profile to another age rating, or delete it, which deletes everything it collected. You can withdraw consent at any time by deleting the profile."]}]$lw$::jsonb),
  ($lw$privacy-choices$lw$, 4, $lw$Your Privacy Choices$lw$, $lw$LiteraryWorm doesn't sell or share personal information for advertising and uses no non-essential cookies (see the Cookie Policy), so there's nothing to opt out of there. Global Privacy Control is honoured. Here are the choices you do have.$lw$, $lw$[{"heading": "Selling and sharing", "paragraphs": ["We don't sell, rent or license your personal information, and we don't share it for cross-context behavioural advertising. If your browser sends a Global Privacy Control signal, we treat it as a request to opt out, and nothing changes because we already don't do either."]}, {"heading": "Cookies and browser storage", "paragraphs": ["We set no cookies of our own and no advertising or analytics cookies. The Cookie Policy lists the strictly necessary things your browser keeps, such as your sign-in session, and how to clear them."]}, {"heading": "Emails and notifications", "paragraphs": ["Turn emails about new releases and offers on or off in Account → Preferences. Service emails, like password resets, always arrive. Book club alerts can be turned off for each club on its page, and browser notifications only appear if you allow them."]}, {"heading": "Your data", "paragraphs": ["In Account you can download a copy of your data, correct your display name, and delete profiles or your whole account. Reading logs, club posts, highlights and uploads can each be deleted whenever you like. The Privacy Policy explains what we keep and for how long."]}]$lw$::jsonb),
  ($lw$terms$lw$, 5, $lw$Terms of Service$lw$, $lw$We are LiteraryWorm ("Company," "we," "us," "our"). We operate the website https://www.literaryworm.com (the "Site"), as well as any other related products and services that refer or link to these legal terms (the "Legal Terms") (collectively, the "Services"). These Legal Terms cover who can have an account, how membership works, what you may do with the books, who owns what, and the license you give us for what you post. You can contact us by email at support@literaryworm.com.$lw$, $lw$[{"heading": "Agreement to our legal terms", "paragraphs": ["These Legal Terms constitute a legally binding agreement made between you, whether personally or on behalf of an entity (\"you\"), and LiteraryWorm, concerning your access to and use of the Services. You agree that by accessing the Services, you have read, understood, and agreed to be bound by all of these Legal Terms. IF YOU DO NOT AGREE WITH ALL OF THESE LEGAL TERMS, THEN YOU ARE EXPRESSLY PROHIBITED FROM USING THE SERVICES AND YOU MUST DISCONTINUE USE IMMEDIATELY.", "Supplemental terms and conditions or documents that may be posted on the Services from time to time, such as our End User License Agreement (https://www.literaryworm.com/legal/eula), are hereby expressly incorporated herein by reference. We may change these Legal Terms from time to time. We'll tell you before changing them in ways that matter, and we'll update the \"Last updated\" date. You will be subject to, and will be deemed to have accepted, the changes in any revised Legal Terms by your continued use of the Services after the date such revised Legal Terms are posted.", "Account holders must be at least 18 years old. People under 18 may use the Services only through a profile, such as a Kids profile, that a parent or guardian adds to their own account and is responsible for.", "We recommend that you print a copy of these Legal Terms for your records."]}, {"heading": "1. Our services", "paragraphs": ["The information provided when using the Services is not intended for distribution to or use by any person or entity in any jurisdiction or country where such distribution or use would be contrary to law or regulation or which would subject us to any registration requirement within such jurisdiction or country. Accordingly, those persons who choose to access the Services from other locations do so on their own initiative and are solely responsible for compliance with local laws, if and to the extent local laws are applicable.", "The Services are not tailored to comply with industry-specific regulations (Health Insurance Portability and Accountability Act (HIPAA), Federal Information Security Management Act (FISMA), etc.), so if your interactions would be subjected to such laws, you may not use the Services. You may not use the Services in a way that would violate the Gramm-Leach-Bliley Act (GLBA)."]}, {"heading": "2. Intellectual property rights", "paragraphs": ["Our intellectual property. We are the owner or the licensee of all intellectual property rights in our Services, including all source code, databases, functionality, software, website designs, audio, video, text, photographs, and graphics in the Services (collectively, the \"Content\"), as well as the trademarks, service marks, and logos contained therein (the \"Marks\"). Section 32 explains which books are in the public domain and who owns the rest.", "Our Content and Marks are protected by copyright and trademark laws (and various other intellectual property rights and unfair competition laws) and treaties in the United States and around the world.", "The Content and Marks are provided in or through the Services \"AS IS\" for your personal, non-commercial use only.", "Your use of our Services. Subject to your compliance with these Legal Terms, including the \"Prohibited activities\" section below, we grant you a non-exclusive, non-transferable, revocable license to access the Services, solely for your personal, non-commercial use. What you may do with the books is set out in section 31.", "Except as set out in this section or elsewhere in our Legal Terms, no part of the Services and no Content or Marks may be copied, reproduced, aggregated, republished, uploaded, posted, publicly displayed, encoded, translated, transmitted, distributed, sold, licensed, or otherwise exploited for any commercial purpose whatsoever, without our express prior written permission.", "If you wish to make any use of the Services, Content, or Marks other than as set out in this section or elsewhere in our Legal Terms, please address your request to: support@literaryworm.com. If we ever grant you the permission to post, reproduce, or publicly display any part of our Services or Content, you must identify us as the owners or licensors of the Services, Content, or Marks and ensure that any copyright or proprietary notice appears or is visible on posting, reproducing, or displaying our Content.", "We reserve all rights not expressly granted to you in and to the Services, Content, and Marks. Being able to see source code we publish doesn't give you a license to use it.", "Any breach of these Intellectual Property Rights will constitute a material breach of our Legal Terms and your right to use our Services will terminate immediately.", "Your submissions. By directly sending us any question, comment, suggestion, idea, feedback, or other information about the Services (\"Submissions\"), you agree to assign to us all intellectual property rights in such Submission. You agree that we shall own this Submission and be entitled to its unrestricted use and dissemination for any lawful purpose, commercial or otherwise, without acknowledgment or compensation to you.", "Your contributions. What you post in the Services (reading logs, club posts, ratings, list names and descriptions, notes and highlights) are \"Contributions\", covered by sections 9, 10 and 33. You own them, and the license you give us is the limited one in section 33. Contributions you make public may be seen by anyone, including through links you share outside the Services.", "You are responsible for what you post or upload. By sending us Submissions and/or posting Contributions, you: confirm that you have read and agree with our \"Prohibited activities\" and will not post, send, publish, upload, or transmit through the Services any Submission nor post any Contribution that is illegal, harassing, hateful, harmful, defamatory, obscene, bullying, abusive, discriminatory, threatening to any person or group, sexually explicit, false, inaccurate, deceitful, or misleading; warrant that any such Submission and/or Contributions are original to you or that you have the necessary rights and licenses to submit them and full authority to grant us the rights in these Legal Terms; and warrant and represent that your Submissions and/or Contributions do not constitute confidential information. You are solely responsible for your Submissions and/or Contributions and you expressly agree to reimburse us for any and all losses that we may suffer because of your breach of (a) this section, (b) any third party's intellectual property rights, or (c) applicable law.", "We may remove your Contributions. Although we have no obligation to monitor any Contributions, we shall have the right to remove any Contributions at any time without notice if in our reasonable opinion we consider such Contributions harmful or in breach of these Legal Terms. If we remove any such Contributions, we may also suspend or disable your account and report you to the authorities.", "Copyright infringement. We respect the intellectual property rights of others. If you believe that any material available on or through the Services infringes upon any copyright you own or control, please refer to section 15 and our Copyright/DMCA page."]}, {"heading": "3. User representations", "paragraphs": ["By using the Services, you represent and warrant that: (1) all registration information you submit will be true, accurate, current, and complete; (2) you will maintain the accuracy of such information and promptly update such registration information as necessary; (3) you have the legal capacity and you agree to comply with these Legal Terms; (4) if you hold an account, you are at least 18 and not a minor in the jurisdiction in which you reside; (5) you will not access the Services through automated or non-human means, whether through a bot, script or otherwise; (6) you will not use the Services for any illegal or unauthorized purpose; and (7) your use of the Services will not violate any applicable law or regulation.", "If you provide any information that is untrue, inaccurate, not current, or incomplete, we have the right to suspend or terminate your account and refuse any and all current or future use of the Services (or any portion thereof)."]}, {"heading": "4. User registration", "paragraphs": ["You need to register to use most of the Services. You agree to keep your password confidential and will be responsible for all use of your account and password. We reserve the right to remove, reclaim, or change a display name or profile name you select if we determine, in our sole discretion, that it is inappropriate, obscene, or otherwise objectionable."]}, {"heading": "5. Purchases and payment", "paragraphs": ["LiteraryWorm doesn't take payment yet: choosing a plan saves it to your account, but no one is charged. This section will apply once paid plans start, and we'll tell you before they do.", "When paid plans start, we expect to accept the following forms of payment: PayPal, Discover, American Express, Mastercard and Visa.", "You agree to provide current, complete, and accurate purchase and account information for all purchases made via the Services. You further agree to promptly update account and payment information, including email address, payment method, and payment card expiration date, so that we can complete your transactions and contact you as needed. Sales tax will be added to the price of purchases as deemed required by us. We may change prices at any time. All payments shall be in US dollars.", "You agree to pay all charges at the prices then in effect for your purchases, and you authorize us to charge your chosen payment provider for any such amounts upon placing your order. We reserve the right to correct any errors or mistakes in pricing, even if we have already requested or received payment.", "We reserve the right to refuse any order placed through the Services. We may, in our sole discretion, limit or cancel quantities purchased per person, per household, or per order. These restrictions may include orders placed by or under the same customer account or the same payment method. We reserve the right to limit or prohibit orders that, in our sole judgment, appear to be placed by dealers, resellers, or distributors."]}, {"heading": "6. Subscriptions", "paragraphs": ["Billing and renewal. Your subscription will continue and automatically renew each month unless canceled. Once paid plans start, you consent to our charging your payment method on a recurring basis without requiring your prior approval for each recurring charge, until such time as you cancel.", "Cancellation. You can cancel your subscription at any time from Account. Your cancellation will take effect at the end of the current paid term. If you have any questions or are unsatisfied with our Services, please email us at support@literaryworm.com.", "Fee changes. We may, from time to time, make changes to the subscription fee and will communicate any price changes to you in accordance with applicable law."]}, {"heading": "7. Software", "paragraphs": ["Our End User License Agreement (https://www.literaryworm.com/legal/eula) governs your use of the LiteraryWorm app, in the browser or installed on a device. Any other software we provide in connection with our Services is licensed to you on a non-exclusive, revocable, personal, and non-transferable basis, solely in connection with our Services and in accordance with these Legal Terms. Any software and any related documentation is provided \"AS IS\" without warranty of any kind, either express or implied, including, without limitation, the implied warranties of merchantability, fitness for a particular purpose, or non-infringement. You accept any and all risk arising out of use or performance of any software. You may not reproduce or redistribute any software except in accordance with the EULA or these Legal Terms."]}, {"heading": "8. Prohibited activities", "paragraphs": ["You may not access or use the Services for any purpose other than that for which we make the Services available. The Services may not be used in connection with any commercial endeavors except those that are specifically endorsed or approved by us.", "As a user of the Services, you agree not to:", "1. Systematically retrieve data or other content from the Services to create or compile, directly or indirectly, a collection, compilation, database, or directory without written permission from us.", "2. Trick, defraud, or mislead us and other users, especially in any attempt to learn sensitive account information such as user passwords or profile PINs.", "3. Circumvent, disable, or otherwise interfere with security-related features of the Services, including features that prevent or restrict the use or copying of any Content or enforce limitations on the use of the Services and/or the Content contained therein, such as daily reading limits and age ratings.", "4. Disparage, tarnish, or otherwise harm, in our opinion, us and/or the Services.", "5. Use any information obtained from the Services in order to harass, abuse, or harm another person.", "6. Make improper use of our support services or submit false reports of abuse or misconduct.", "7. Use the Services in a manner inconsistent with any applicable laws or regulations.", "8. Engage in unauthorized framing of or linking to the Services.", "9. Upload or transmit (or attempt to upload or to transmit) viruses, Trojan horses, or other material, including excessive use of capital letters and spamming (continuous posting of repetitive text), that interferes with any party's uninterrupted use and enjoyment of the Services or modifies, impairs, disrupts, alters, or interferes with the use, features, functions, operation, or maintenance of the Services.", "10. Engage in any automated use of the system, such as using scripts to send comments or messages, or using any data mining, robots, or similar data gathering and extraction tools.", "11. Delete the copyright or other proprietary rights notice from any Content.", "12. Attempt to impersonate another user or person or use the display name of another user.", "13. Upload or transmit (or attempt to upload or to transmit) any material that acts as a passive or active information collection or transmission mechanism, including without limitation, clear graphics interchange formats (\"gifs\"), 1×1 pixels, web bugs, cookies, or other similar devices (sometimes referred to as \"spyware\" or \"passive collection mechanisms\" or \"pcms\").", "14. Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services, including by trying to get around the limits on AI summaries and Ask the book.", "15. Harass, annoy, intimidate, or threaten any of our employees or agents engaged in providing any portion of the Services to you.", "16. Attempt to bypass any measures of the Services designed to prevent or restrict access to the Services, or any portion of the Services.", "17. Copy or adapt the Services' software, including but not limited to HTML, JavaScript, or other code.", "18. Except as permitted by applicable law, decipher, decompile, disassemble, or reverse engineer any of the software comprising or in any way making up a part of the Services.", "19. Except as may be the result of standard search engine or Internet browser usage, or the Services' own Read offline feature, use, launch, develop, or distribute any automated system, including without limitation, any spider, robot, cheat utility, scraper, or offline reader that accesses the Services, or use or launch any unauthorized script or other software.", "20. Use a buying agent or purchasing agent to make purchases on the Services.", "21. Make any unauthorized use of the Services, including collecting display names and/or email addresses of users by electronic or other means for the purpose of sending unsolicited email, or creating user accounts by automated means or under false pretenses.", "22. Use the Services as part of any effort to compete with us or otherwise use the Services and/or the Content for any revenue-generating endeavor or commercial enterprise.", "23. Sell or otherwise transfer your account or a profile.", "24. Use the Services to advertise or offer to sell goods and services."]}, {"heading": "9. User generated contributions", "paragraphs": ["The Services invite you to post Contributions: reading logs (shown on a book's public page with your display name), book club posts (seen by the club's members), ratings, lists you choose to share by link, and private notes and highlights. Contributions you make public may be viewable by other users of the Services and by anyone you share a link with. When you create or make available any Contributions, you thereby represent and warrant that:", "1. The creation, distribution, transmission, public display, or performance, and the accessing, downloading, or copying of your Contributions do not and will not infringe the proprietary rights, including but not limited to the copyright, patent, trademark, trade secret, or moral rights of any third party.", "2. You are the creator and owner of or have the necessary licenses, rights, consents, releases, and permissions to use and to authorize us, the Services, and other users of the Services to use your Contributions in any manner contemplated by the Services and these Legal Terms.", "3. You have the written consent, release, and/or permission of each and every identifiable individual person in your Contributions to use the name or likeness of each and every such identifiable individual person to enable inclusion and use of your Contributions in any manner contemplated by the Services and these Legal Terms.", "4. Your Contributions are not false, inaccurate, or misleading.", "5. Your Contributions are not unsolicited or unauthorized advertising, promotional materials, pyramid schemes, chain letters, spam, mass mailings, or other forms of solicitation.", "6. Your Contributions are not obscene, lewd, lascivious, filthy, violent, harassing, libelous, slanderous, or otherwise objectionable (as determined by us).", "7. Your Contributions do not ridicule, mock, disparage, intimidate, or abuse anyone.", "8. Your Contributions are not used to harass or threaten (in the legal sense of those terms) any other person and to promote violence against a specific person or class of people.", "9. Your Contributions do not violate any applicable law, regulation, or rule.", "10. Your Contributions do not violate the privacy or publicity rights of any third party.", "11. Your Contributions do not violate any applicable law concerning child sexual abuse material, or otherwise intended to protect the health or well-being of minors.", "12. Your Contributions do not include any offensive comments that are connected to race, national origin, gender, sexual preference, or physical handicap.", "13. Your Contributions do not otherwise violate, or link to material that violates, any provision of these Legal Terms, or any applicable law or regulation.", "Any use of the Services in violation of the foregoing violates these Legal Terms and may result in, among other things, termination or suspension of your rights to use the Services."]}, {"heading": "10. Contribution license", "paragraphs": ["We do not assert any ownership over your Contributions. You retain full ownership of all of your Contributions and any intellectual property rights or other proprietary rights associated with your Contributions. The only license you give us is the one in section 33: to store, copy and display them where and to whom you posted them, so we can run the features you use.", "We are not liable for any statements or representations in your Contributions provided by you in any area on the Services. You are solely responsible for your Contributions to the Services and you expressly agree to exonerate us from any and all responsibility and to refrain from any legal action against us regarding your Contributions.", "We have the right, in our sole and absolute discretion, to remove or hide any Contributions at any time and for any reason, without notice. We have no obligation to monitor your Contributions."]}, {"heading": "11. Guidelines for reviews", "paragraphs": ["You can rate books and write about them in reading logs. When you do, you must comply with the following criteria: (1) you should have firsthand experience with the book you're reviewing; (2) your reviews should not contain offensive profanity, or abusive, racist, offensive, or hateful language; (3) your reviews should not contain discriminatory references based on religion, race, gender, national origin, age, marital status, sexual orientation, or disability; (4) your reviews should not contain references to illegal activity; (5) you should not be affiliated with competitors if posting negative reviews; (6) you should not make any conclusions as to the legality of conduct; (7) you may not post any false or misleading statements; and (8) you may not organize a campaign encouraging others to post reviews, whether positive or negative.", "We may remove reviews in our sole discretion. We have absolutely no obligation to screen reviews or to delete reviews, even if anyone considers reviews objectionable or inaccurate. Reviews are not endorsed by us, and do not necessarily represent our opinions or the views of any of our affiliates or partners. We do not assume liability for any review or for any claims, liabilities, or losses resulting from any review. Reviews are Contributions, so you keep them, and the license you give us is the one in section 33."]}, {"heading": "12. Third-party websites and content", "paragraphs": ["The Services contain (or you may be sent via the Site) links to other websites (\"Third-Party Websites\"), such as Google Books, the Internet Archive, LibriVox and Project Gutenberg, as well as articles, photographs, text, graphics, pictures, designs, music, sound, video, information, applications, software, and other content or items belonging to or originating from third parties (\"Third-Party Content\"), such as book details and covers from Google Books and recordings from LibriVox. Such Third-Party Websites and Third-Party Content are not investigated, monitored, or checked for accuracy, appropriateness, or completeness by us, and we are not responsible for any Third-Party Websites accessed through the Services or any Third-Party Content posted on, available through, or installed from the Services, including the content, accuracy, offensiveness, opinions, reliability, privacy practices, or other policies of or contained in the Third-Party Websites or the Third-Party Content. Inclusion of, linking to, or permitting the use or installation of any Third-Party Websites or any Third-Party Content does not imply approval or endorsement thereof by us. If you decide to leave the Services and access the Third-Party Websites or to use or install any Third-Party Content, you do so at your own risk, and you should be aware these Legal Terms no longer govern. You should review the applicable terms and policies, including privacy and data gathering practices, of any website to which you navigate from the Services or relating to any applications you use or install from the Services. Any purchases you make through Third-Party Websites will be through other websites and from other companies, and we take no responsibility whatsoever in relation to such purchases which are exclusively between you and the applicable third party. You agree and acknowledge that we do not endorse the products or services offered on Third-Party Websites and you shall hold us blameless from any harm caused by your purchase of such products or services. Additionally, you shall hold us blameless from any losses sustained by you or harm caused to you relating to or resulting in any way from any Third-Party Content or any contact with Third-Party Websites."]}, {"heading": "13. Services management", "paragraphs": ["We reserve the right, but not the obligation, to: (1) monitor the Services for violations of these Legal Terms; (2) take appropriate legal action against anyone who, in our sole discretion, violates the law or these Legal Terms, including without limitation, reporting such user to law enforcement authorities; (3) in our sole discretion and without limitation, refuse, restrict access to, limit the availability of, or disable (to the extent technologically feasible) any of your Contributions or any portion thereof; (4) in our sole discretion and without limitation, notice, or liability, to remove from the Services or otherwise disable all files and content that are excessive in size or are in any way burdensome to our systems; and (5) otherwise manage the Services in a manner designed to protect our rights and property and to facilitate the proper functioning of the Services."]}, {"heading": "14. Privacy policy", "paragraphs": ["We care about data privacy and security. Please review our Privacy Policy: https://www.literaryworm.com/legal/privacy. By using the Services, you agree to be bound by our Privacy Policy, which is incorporated into these Legal Terms. Please be advised the Services are hosted in the United States. If you access the Services from any other region of the world with laws or other requirements governing personal data collection, use, or disclosure that differ from applicable laws in the United States, then through your continued use of the Services, you are transferring your data to the United States, and you expressly consent to have your data transferred to and processed in the United States."]}, {"heading": "15. Copyright infringements", "paragraphs": ["We respect the intellectual property rights of others. If you believe that any material available on or through the Services infringes upon any copyright you own or control, please follow the steps on our Copyright/DMCA page (a \"Notification\"). We will tell the member who posted the material that it was removed. Please be advised that pursuant to applicable law you may be held liable for damages if you make material misrepresentations in a Notification. Thus, if you are not sure that material located on or linked to by the Services infringes your copyright, you should consider first contacting an attorney."]}, {"heading": "16. Term and termination", "paragraphs": ["These Legal Terms shall remain in full force and effect while you use the Services. You can end them at any time by deleting your account from Account. WITHOUT LIMITING ANY OTHER PROVISION OF THESE LEGAL TERMS, WE RESERVE THE RIGHT TO, IN OUR SOLE DISCRETION AND WITHOUT NOTICE OR LIABILITY, DENY ACCESS TO AND USE OF THE SERVICES (INCLUDING BLOCKING CERTAIN IP ADDRESSES), TO ANY PERSON FOR ANY REASON OR FOR NO REASON, INCLUDING WITHOUT LIMITATION FOR BREACH OF ANY REPRESENTATION, WARRANTY, OR COVENANT CONTAINED IN THESE LEGAL TERMS OR OF ANY APPLICABLE LAW OR REGULATION. WE MAY TERMINATE YOUR USE OR PARTICIPATION IN THE SERVICES OR DELETE YOUR ACCOUNT AND ANY CONTENT OR INFORMATION THAT YOU POSTED AT ANY TIME, WITHOUT WARNING, IN OUR SOLE DISCRETION.", "If we terminate or suspend your account for any reason, you are prohibited from registering and creating a new account under your name, a fake or borrowed name, or the name of any third party, even if you may be acting on behalf of the third party. In addition to terminating or suspending your account, we reserve the right to take appropriate legal action, including without limitation pursuing civil, criminal, and injunctive redress."]}, {"heading": "17. Modifications and interruptions", "paragraphs": ["We reserve the right to change, modify, or remove the contents of the Services at any time or for any reason at our sole discretion without notice. However, we have no obligation to update any information on our Services. We will not be liable to you or any third party for any modification, price change, suspension, or discontinuance of the Services.", "We cannot guarantee the Services will be available at all times. We may experience hardware, software, or other problems or need to perform maintenance related to the Services, resulting in interruptions, delays, or errors. Our Status page shows whether the Services are working. We reserve the right to change, revise, update, suspend, discontinue, or otherwise modify the Services at any time or for any reason without notice to you. You agree that we have no liability whatsoever for any loss, damage, or inconvenience caused by your inability to access or use the Services during any downtime or discontinuance of the Services. Nothing in these Legal Terms will be construed to obligate us to maintain and support the Services or to supply any corrections, updates, or releases in connection therewith."]}, {"heading": "18. Governing law", "paragraphs": ["These Legal Terms and your use of the Services are governed by and construed in accordance with the laws of the State of Illinois applicable to agreements made and to be entirely performed within the State of Illinois, without regard to its conflict of law principles."]}, {"heading": "19. Dispute resolution", "paragraphs": ["Informal negotiations. To expedite resolution and control the cost of any dispute, controversy, or claim related to these Legal Terms (each a \"Dispute\" and collectively, the \"Disputes\") brought by either you or us (individually, a \"Party\" and collectively, the \"Parties\"), the Parties agree to first attempt to negotiate any Dispute (except those Disputes expressly provided below) informally for at least thirty (30) days before initiating arbitration. Such informal negotiations commence upon written notice from one Party to the other Party.", "Binding arbitration. If the Parties are unable to resolve a Dispute through informal negotiations, the Dispute (except those Disputes expressly excluded below) will be finally and exclusively resolved by binding arbitration. YOU UNDERSTAND THAT WITHOUT THIS PROVISION, YOU WOULD HAVE THE RIGHT TO SUE IN COURT AND HAVE A JURY TRIAL. The arbitration shall be commenced and conducted under the Commercial Arbitration Rules of the American Arbitration Association (\"AAA\") and, where appropriate, the AAA's Supplementary Procedures for Consumer Related Disputes (\"AAA Consumer Rules\"), both of which are available at the American Arbitration Association (AAA) website. Your arbitration fees and your share of arbitrator compensation shall be governed by the AAA Consumer Rules and, where appropriate, limited by the AAA Consumer Rules. The arbitration may be conducted in person, through the submission of documents, by phone, or online. The arbitrator will make a decision in writing, but need not provide a statement of reasons unless requested by either Party. The arbitrator must follow applicable law, and any award may be challenged if the arbitrator fails to do so. Except where otherwise required by the applicable AAA rules or applicable law, the arbitration will take place in Cook County, Illinois. Except as otherwise provided herein, the Parties may litigate in court to compel arbitration, stay proceedings pending arbitration, or to confirm, modify, vacate, or enter judgment on the award entered by the arbitrator.", "If for any reason, a Dispute proceeds in court rather than arbitration, the Dispute shall be commenced or prosecuted in the state and federal courts located in Cook County, Illinois, and the Parties hereby consent to, and waive all defenses of lack of personal jurisdiction, and forum non conveniens with respect to venue and jurisdiction in such state and federal courts. Application of the United Nations Convention on Contracts for the International Sale of Goods and the Uniform Computer Information Transaction Act (UCITA) are excluded from these Legal Terms.", "In no event shall any Dispute brought by either Party related in any way to the Services be commenced more than one (1) year after the cause of action arose. If this provision is found to be illegal or unenforceable, then neither Party will elect to arbitrate any Dispute falling within that portion of this provision found to be illegal or unenforceable and such Dispute shall be decided by a court of competent jurisdiction within the courts listed for jurisdiction above, and the Parties agree to submit to the personal jurisdiction of that court.", "Restrictions. The Parties agree that any arbitration shall be limited to the Dispute between the Parties individually. To the full extent permitted by law, (a) no arbitration shall be joined with any other proceeding; (b) there is no right or authority for any Dispute to be arbitrated on a class-action basis or to utilize class action procedures; and (c) there is no right or authority for any Dispute to be brought in a purported representative capacity on behalf of the general public or any other persons.", "Exceptions to informal negotiations and arbitration. The Parties agree that the following Disputes are not subject to the above provisions concerning informal negotiations and binding arbitration: (a) any Disputes seeking to enforce or protect, or concerning the validity of, any of the intellectual property rights of a Party; (b) any Dispute related to, or arising from, allegations of theft, piracy, invasion of privacy, or unauthorized use; and (c) any claim for injunctive relief. If this provision is found to be illegal or unenforceable, then neither Party will elect to arbitrate any Dispute falling within that portion of this provision found to be illegal or unenforceable and such Dispute shall be decided by a court of competent jurisdiction within the courts listed for jurisdiction above, and the Parties agree to submit to the personal jurisdiction of that court."]}, {"heading": "20. Corrections", "paragraphs": ["There may be information on the Services that contains typographical errors, inaccuracies, or omissions, including descriptions, pricing, availability, and various other information. We reserve the right to correct any errors, inaccuracies, or omissions and to change or update the information on the Services at any time, without prior notice."]}, {"heading": "21. Disclaimer", "paragraphs": ["THE SERVICES ARE PROVIDED ON AN AS-IS AND AS-AVAILABLE BASIS. YOU AGREE THAT YOUR USE OF THE SERVICES WILL BE AT YOUR SOLE RISK. TO THE FULLEST EXTENT PERMITTED BY LAW, WE DISCLAIM ALL WARRANTIES, EXPRESS OR IMPLIED, IN CONNECTION WITH THE SERVICES AND YOUR USE THEREOF, INCLUDING, WITHOUT LIMITATION, THE IMPLIED WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, AND NON-INFRINGEMENT. WE MAKE NO WARRANTIES OR REPRESENTATIONS ABOUT THE ACCURACY OR COMPLETENESS OF THE SERVICES' CONTENT (INCLUDING BOOK DETAILS FROM GOOGLE BOOKS AND SUMMARIES AND ANSWERS WRITTEN BY AI) OR THE CONTENT OF ANY WEBSITES OR MOBILE APPLICATIONS LINKED TO THE SERVICES AND WE WILL ASSUME NO LIABILITY OR RESPONSIBILITY FOR ANY (1) ERRORS, MISTAKES, OR INACCURACIES OF CONTENT AND MATERIALS, (2) PERSONAL INJURY OR PROPERTY DAMAGE, OF ANY NATURE WHATSOEVER, RESULTING FROM YOUR ACCESS TO AND USE OF THE SERVICES, (3) ANY UNAUTHORIZED ACCESS TO OR USE OF OUR SECURE SERVERS AND/OR ANY AND ALL PERSONAL INFORMATION STORED THEREIN, (4) ANY INTERRUPTION OR CESSATION OF TRANSMISSION TO OR FROM THE SERVICES, (5) ANY BUGS, VIRUSES, TROJAN HORSES, OR THE LIKE WHICH MAY BE TRANSMITTED TO OR THROUGH THE SERVICES BY ANY THIRD PARTY, AND/OR (6) ANY ERRORS OR OMISSIONS IN ANY CONTENT AND MATERIALS OR FOR ANY LOSS OR DAMAGE OF ANY KIND INCURRED AS A RESULT OF THE USE OF ANY CONTENT POSTED, TRANSMITTED, OR OTHERWISE MADE AVAILABLE VIA THE SERVICES. WE DO NOT WARRANT, ENDORSE, GUARANTEE, OR ASSUME RESPONSIBILITY FOR ANY PRODUCT OR SERVICE OFFERED BY A THIRD PARTY THROUGH THE SERVICES OR ANY HYPERLINKED WEBSITE, AND WE WILL NOT BE A PARTY TO OR IN ANY WAY BE RESPONSIBLE FOR MONITORING ANY TRANSACTION BETWEEN YOU AND ANY THIRD-PARTY PROVIDERS OF PRODUCTS OR SERVICES. AS WITH THE PURCHASE OF A PRODUCT OR SERVICE THROUGH ANY MEDIUM OR IN ANY ENVIRONMENT, YOU SHOULD USE YOUR BEST JUDGMENT AND EXERCISE CAUTION WHERE APPROPRIATE."]}, {"heading": "22. Limitations of liability", "paragraphs": ["IN NO EVENT WILL WE OR OUR DIRECTORS, EMPLOYEES, OR AGENTS BE LIABLE TO YOU OR ANY THIRD PARTY FOR ANY DIRECT, INDIRECT, CONSEQUENTIAL, EXEMPLARY, INCIDENTAL, SPECIAL, OR PUNITIVE DAMAGES, INCLUDING LOST PROFIT, LOST REVENUE, LOSS OF DATA, OR OTHER DAMAGES ARISING FROM YOUR USE OF THE SERVICES, EVEN IF WE HAVE BEEN ADVISED OF THE POSSIBILITY OF SUCH DAMAGES. NOTWITHSTANDING ANYTHING TO THE CONTRARY CONTAINED HEREIN, OUR LIABILITY TO YOU FOR ANY CAUSE WHATSOEVER AND REGARDLESS OF THE FORM OF THE ACTION, WILL AT ALL TIMES BE LIMITED TO THE AMOUNT PAID, IF ANY, BY YOU TO US DURING THE SIX (6) MONTH PERIOD PRIOR TO ANY CAUSE OF ACTION ARISING. CERTAIN US STATE LAWS AND INTERNATIONAL LAWS DO NOT ALLOW LIMITATIONS ON IMPLIED WARRANTIES OR THE EXCLUSION OR LIMITATION OF CERTAIN DAMAGES. IF THESE LAWS APPLY TO YOU, SOME OR ALL OF THE ABOVE DISCLAIMERS OR LIMITATIONS MAY NOT APPLY TO YOU, AND YOU MAY HAVE ADDITIONAL RIGHTS."]}, {"heading": "23. Indemnification", "paragraphs": ["You agree to defend, indemnify, and hold us harmless, including our subsidiaries, affiliates, and all of our respective officers, agents, partners, and employees, from and against any loss, damage, liability, claim, or demand, including reasonable attorneys' fees and expenses, made by any third party due to or arising out of: (1) your Contributions; (2) use of the Services; (3) breach of these Legal Terms; (4) any breach of your representations and warranties set forth in these Legal Terms; (5) your violation of the rights of a third party, including but not limited to intellectual property rights; or (6) any overt harmful act toward any other user of the Services with whom you connected via the Services. Notwithstanding the foregoing, we reserve the right, at your expense, to assume the exclusive defense and control of any matter for which you are required to indemnify us, and you agree to cooperate, at your expense, with our defense of such claims. We will use reasonable efforts to notify you of any such claim, action, or proceeding which is subject to this indemnification upon becoming aware of it."]}, {"heading": "24. User data", "paragraphs": ["We will maintain certain data that you transmit to the Services for the purpose of managing the performance of the Services, as well as data relating to your use of the Services, as our Privacy Policy describes. You can download a copy of your data at any time from Account (Download my data). To the extent permitted by law, you are responsible for keeping your own copy of anything you can't afford to lose, and you agree that we shall have no liability to you for any loss or corruption of any such data."]}, {"heading": "25. Electronic communications, transactions, and signatures", "paragraphs": ["Visiting the Services, sending us emails, and completing online forms constitute electronic communications. You consent to receive electronic communications, and you agree that all agreements, notices, disclosures, and other communications we provide to you electronically, via email and on the Services, satisfy any legal requirement that such communication be in writing. YOU HEREBY AGREE TO THE USE OF ELECTRONIC SIGNATURES, CONTRACTS, ORDERS, AND OTHER RECORDS, AND TO ELECTRONIC DELIVERY OF NOTICES, POLICIES, AND RECORDS OF TRANSACTIONS INITIATED OR COMPLETED BY US OR VIA THE SERVICES. You hereby waive any rights or requirements under any statutes, regulations, rules, ordinances, or other laws in any jurisdiction which require an original signature or delivery or retention of non-electronic records, or to payments or the granting of credits by any means other than electronic means."]}, {"heading": "26. SMS text messaging", "paragraphs": ["LiteraryWorm doesn't send text messages (SMS) and doesn't ask for your phone number. If we ever start a text messaging program, we'll add its terms here, including how to opt out, before it begins."]}, {"heading": "27. California users and residents", "paragraphs": ["If any complaint with us is not satisfactorily resolved, you can contact the Complaint Assistance Unit of the Division of Consumer Services of the California Department of Consumer Affairs in writing at 1625 North Market Blvd., Suite N 112, Sacramento, California 95834 or by telephone at (800) 952-5210 or (916) 445-1254."]}, {"heading": "28. Miscellaneous", "paragraphs": ["These Legal Terms and any policies or operating rules posted by us on the Services or in respect to the Services constitute the entire agreement and understanding between you and us. Our failure to exercise or enforce any right or provision of these Legal Terms shall not operate as a waiver of such right or provision. These Legal Terms operate to the fullest extent permissible by law. We may assign any or all of our rights and obligations to others at any time. We shall not be responsible or liable for any loss, damage, delay, or failure to act caused by any cause beyond our reasonable control. If any provision or part of a provision of these Legal Terms is determined to be unlawful, void, or unenforceable, that provision or part of the provision is deemed severable from these Legal Terms and does not affect the validity and enforceability of any remaining provisions. There is no joint venture, partnership, employment or agency relationship created between you and us as a result of these Legal Terms or use of the Services. You agree that these Legal Terms will not be construed against us by virtue of having drafted them. You hereby waive any and all defenses you may have based on the electronic form of these Legal Terms and the lack of signing by the parties hereto to execute these Legal Terms."]}, {"heading": "29. Your account", "paragraphs": ["Account holders must be 18 or older. You may add profiles for people in your household, including Kids profiles with your consent, and you're responsible for how they're used.", "Keep your password private. You can change it, and delete your account, from Account at any time."]}, {"heading": "30. Membership", "paragraphs": ["Plans renew automatically each month until you cancel, which you can do online at any time; reading continues until the end of the period you've paid for. You can pause and resume from Account.", "LiteraryWorm is currently a demonstration: choosing a plan saves it to your account, but no payment is taken."]}, {"heading": "31. Your licence to read and listen", "paragraphs": ["While your membership is active, we give you a personal, non-exclusive, non-transferable, revocable licence to read and listen to the books in LiteraryWorm for your own and your household's non-commercial use, in the app.", "You may not copy, sell, share, broadcast or publicly perform the books, remove or get around any protection on them, or use them to train AI models. Books saved for offline reading stay in the app on your device.", "This licence doesn't apply to public-domain works themselves, which anyone may use freely; it covers our app, our edition and our service."]}, {"heading": "32. Who owns the books and the app", "paragraphs": ["Public-domain titles: the texts come from Project Gutenberg and the recordings from LibriVox, whose volunteers release their recordings into the public domain. These works are in the public domain in the United States; they may not be everywhere, so check your country's rules before using them outside LiteraryWorm.", "Other LiteraryWorm titles show sample pages, not the published books. Book details and covers from Google Books belong to their publishers and rights holders and are shown under Google's terms.", "Summaries and Ask the book answers are written by AI (Claude) and labelled so. They may be wrong; they're provided for your own reading and may not be republished as LiteraryWorm's.", "The LiteraryWorm name, logo, design and software belong to LiteraryWorm. Using the service doesn't give you any rights in them beyond these Terms."]}, {"heading": "33. What you post, and the license you give us", "paragraphs": ["You own what you write: reading logs, club posts, list names and descriptions, notes and highlights.", "So we can run the features you use, you give LiteraryWorm a worldwide, non-exclusive, royalty-free licence to store, copy and display what you post, only where and to whom you posted it (logs on the book's public page with your display name, club posts to the club, shared lists to anyone with the link). The licence ends when you delete the content or your account, except for copies already made by others, such as someone else's screenshot.", "Notes, highlights and private lists are never shown to anyone else."]}, {"heading": "34. Books you upload", "paragraphs": ["Upload only books you have the right to read in this way, such as DRM-free books you've bought or works in the public domain. Don't upload books you don't have rights to, and don't remove DRM to upload them.", "Your uploads stay private to the profile that added them. We store their text only to show it to you, claim no rights in them, and delete them when you do or when you delete the profile or account."]}, {"heading": "35. Rules, changes and ending", "paragraphs": ["Don't post anything unlawful, hateful, harassing or infringing, impersonate others, spam clubs, or try to break or overload the service. We may remove content that breaks these rules and suspend accounts that keep doing so, including repeat copyright infringers (see Copyright/DMCA).", "LiteraryWorm is provided as is. We'll tell you before changing these Terms in ways that matter, and you can cancel or delete your account at any time."]}, {"heading": "36. Contact us", "paragraphs": ["In order to resolve a complaint regarding the Services or to receive further information regarding use of the Services, please contact us at: LiteraryWorm, support@literaryworm.com."]}]$lw$::jsonb),
  ($lw$eula$lw$, 6, $lw$End User License Agreement$lw$, $lw$LiteraryWorm is licensed to You (End-User) by LiteraryWorm ("Licensor"), for use only under the terms of this License Agreement. By using the Licensed Application at https://www.literaryworm.com, or installing it on a device from your browser, and any update to it, You agree to be bound by all of the terms and conditions of this License Agreement. It sits alongside our Terms of Service; where they cover the same thing, the Terms of Service apply.$lw$, $lw$[{"heading": "1. The application", "paragraphs": ["LiteraryWorm (\"Licensed Application\") is a piece of software created to read and listen to books online. It runs in a web browser and can be installed from the browser on phones, tablets and computers (\"Devices\"). It is used to read ebooks and listen to audiobooks, review them, and share opinions with other readers. The books we offer in full are in the public domain and have no DRM.", "The Licensed Application is not tailored to comply with industry-specific regulations (Health Insurance Portability and Accountability Act (HIPAA), Federal Information Security Management Act (FISMA), etc.), so if your interactions would be subjected to such laws, you may not use this Licensed Application. You may not use the Licensed Application in a way that would violate the Gramm-Leach-Bliley Act (GLBA).", "The Licensed Application isn't sold through an app store, and no app store or other third party is a party to this License Agreement. LiteraryWorm is solely responsible for the Licensed Application and its content."]}, {"heading": "2. Scope of license", "paragraphs": ["2.1 You are given a non-transferable, non-exclusive, non-sublicensable license to use the Licensed Application on any Devices that You (End-User) own or control, with the exception that people in your household may use it through the profiles on your account, as the Terms of Service allow.", "2.2 This license will also govern any updates of the Licensed Application provided by Licensor that replace, repair, and/or supplement the first Licensed Application, unless a separate license is provided for such update, in which case the terms of that new license will govern.", "2.3 You may not share or make the Licensed Application available to third parties (except through features the Licensed Application offers, such as shared lists and book clubs, or with LiteraryWorm's prior written consent), sell, rent, lend, lease or otherwise redistribute the Licensed Application.", "2.4 You may not reverse engineer, translate, disassemble, integrate, decompile, remove, modify, combine, create derivative works or updates of, adapt, or attempt to derive the source code of the Licensed Application, or any part thereof, except with LiteraryWorm's prior written consent or where the law allows it. Being able to see source code we publish doesn't give You a license to use it.", "2.5 You may not copy (excluding when expressly authorized by this license) or alter the Licensed Application or portions thereof. Books You save for offline reading are kept in the Licensed Application on that Device only. You may not remove any intellectual property notices. If you sell or give away a Device, sign out of LiteraryWorm on it first; signing out removes books you uploaded from that Device, and you can clear books saved for offline from the Licensed Application or your browser.", "2.6 Violations of the obligations mentioned above, as well as the attempt of such infringement, may be subject to prosecution and damages.", "2.7 Licensor reserves the right to modify the terms and conditions of licensing. We'll tell you before changing them in ways that matter.", "2.8 Nothing in this license should be interpreted to restrict third-party terms. When using the Licensed Application, You must ensure that You comply with applicable third-party terms and conditions."]}, {"heading": "3. Technical requirements", "paragraphs": ["3.1 The Licensed Application requires a current version of Chrome, Edge, Firefox or Safari and an internet connection, except for books saved for offline reading. Licensor recommends keeping your browser up to date.", "3.2 Licensor attempts to keep the Licensed Application updated so that it works with new versions of browsers and new hardware. You are not granted rights to claim such an update.", "3.3 You acknowledge that it is Your responsibility to confirm and determine that the Device on which You intend to use the Licensed Application satisfies the technical specifications mentioned above.", "3.4 Licensor reserves the right to modify the technical specifications as it sees appropriate at any time."]}, {"heading": "4. Maintenance and support", "paragraphs": ["4.1 The Licensor is solely responsible for providing any maintenance and support services for this Licensed Application. You can reach the Licensor at support@literaryworm.com.", "4.2 No app store or other third party has any obligation to provide maintenance and support services for the Licensed Application."]}, {"heading": "5. Use of data", "paragraphs": ["You acknowledge that Licensor stores and can access Your account, Your profiles and what You read, save and share in the Licensed Application, so that it can provide it to You, and that Licensor's use of that information is subject to Your legal agreements with Licensor and Licensor's privacy policy: https://www.literaryworm.com/legal/privacy.", "You acknowledge that the Licensor and its hosting providers may collect technical data, such as your browser type, IP address and error reports, to keep the Licensed Application secure and working and to offer product support, and a short label for each Device you're signed in on (such as \"Chrome on Windows\") so you can send a book to another Device. Licensor doesn't use this information for advertising."]}, {"heading": "6. User-generated contributions", "paragraphs": ["The Licensed Application invites you to contribute content: reading logs (shown on a book's public page with your display name), book club posts (seen by the club's members), ratings, lists you choose to share by link, and private notes and highlights (collectively, \"Contributions\"). Contributions you make public may be viewable by anyone, including through links shared outside the Licensed Application. When you create or make available any Contributions, you thereby represent and warrant that:", "1. The creation, distribution, transmission, public display, or performance, and the accessing, downloading, or copying of your Contributions do not and will not infringe the proprietary rights, including but not limited to the copyright, patent, trademark, trade secret, or moral rights of any third party.", "2. You are the creator and owner of or have the necessary licenses, rights, consents, releases, and permissions to use and to authorize us, the Licensed Application, and other users of the Licensed Application to use your Contributions in any manner contemplated by the Licensed Application and this License Agreement.", "3. You have the written consent, release, and/or permission of each and every identifiable individual person in your Contributions to use the name or likeness of each and every such identifiable individual person to enable inclusion and use of your Contributions in any manner contemplated by the Licensed Application and this License Agreement.", "4. Your Contributions are not false, inaccurate, or misleading.", "5. Your Contributions are not unsolicited or unauthorized advertising, promotional materials, pyramid schemes, chain letters, spam, mass mailings, or other forms of solicitation.", "6. Your Contributions are not obscene, lewd, lascivious, filthy, violent, harassing, libelous, slanderous, or otherwise objectionable (as determined by us).", "7. Your Contributions do not ridicule, mock, disparage, intimidate, or abuse anyone.", "8. Your Contributions are not used to harass or threaten (in the legal sense of those terms) any other person and to promote violence against a specific person or class of people.", "9. Your Contributions do not violate any applicable law, regulation, or rule.", "10. Your Contributions do not violate the privacy or publicity rights of any third party.", "11. Your Contributions do not violate any applicable law concerning child sexual abuse material, or otherwise intended to protect the health or well-being of minors.", "12. Your Contributions do not include any offensive comments that are connected to race, national origin, gender, sexual preference, or physical handicap.", "13. Your Contributions do not otherwise violate, or link to material that violates, any provision of this License Agreement, or any applicable law or regulation.", "Any use of the Licensed Application in violation of the foregoing violates this License Agreement and may result in, among other things, termination or suspension of your rights to use the Licensed Application."]}, {"heading": "7. Contribution license", "paragraphs": ["You own your Contributions. By posting them, you give LiteraryWorm the license described in the Terms of Service (\"What you post, and the licence you give us\"): a worldwide, non-exclusive, royalty-free license to store, copy and display your Contributions, only where and to whom you posted them, so we can run the features you use. The license ends when you delete the Contribution or your account, except for copies already made by others. Notes, highlights and private lists are never shown to anyone else.", "We are not liable for any statements or representations in your Contributions. You are solely responsible for your Contributions to the Licensed Application and you expressly agree to exonerate us from any and all responsibility and to refrain from any legal action against us regarding your Contributions.", "We may remove Contributions that break this License Agreement or the Terms of Service, at any time and without notice. We have no obligation to monitor your Contributions."]}, {"heading": "8. Liability", "paragraphs": ["8.1 Licensor's responsibility in the case of violation of obligations and tort shall be limited to intent and gross negligence. Only in case of a breach of essential contractual duties (cardinal obligations), Licensor shall also be liable in case of slight negligence. In any case, liability shall be limited to the foreseeable, contractually typical damages. The limitation mentioned above does not apply to injuries to life, limb, or health.", "8.2 Licensor takes no accountability or responsibility for any damages caused due to a breach of duties according to Section 2 of this License Agreement. To avoid data loss, You can download a copy of your data at any time from Account (Download my data). You are aware that in case of alterations or manipulations of the Licensed Application, You may not have access to the Licensed Application."]}, {"heading": "9. Warranty", "paragraphs": ["9.1 Licensor warrants that the Licensed Application is free of spyware, trojan horses, viruses, or any other malware at the time You use it. Licensor warrants that the Licensed Application works as described in Help.", "9.2 No warranty is provided for the Licensed Application that is not executable on the Device, that has been unauthorizedly modified, handled inappropriately or culpably, combined or installed with inappropriate hardware or software, used with inappropriate accessories, regardless if by Yourself or by third parties, or if there are any other reasons outside of LiteraryWorm's sphere of influence that affect the executability of the Licensed Application.", "9.3 Please notify LiteraryWorm about issues You discover without delay by email at support@literaryworm.com. The defect report will be taken into consideration and further investigated if it has been emailed within a period of seven (7) days after discovery.", "9.4 If we confirm that the Licensed Application is defective, LiteraryWorm reserves a choice to remedy the situation either by means of solving the defect or substitute delivery.", "9.5 LiteraryWorm doesn't take payment yet, so there is no purchase price to refund. If paid memberships are added, the Terms of Service will say how refunds work.", "9.6 If the user is an entrepreneur, any claim based on faults expires after a statutory period of limitation amounting to twelve (12) months after the Licensed Application was made available to the user. The statutory periods of limitation given by law apply for users who are consumers."]}, {"heading": "10. Product claims", "paragraphs": ["LiteraryWorm is responsible for addressing any claims of the End-User or any third party relating to the Licensed Application or the End-User's possession and/or use of that Licensed Application, including, but not limited to: (i) product liability claims; (ii) any claim that the Licensed Application fails to conform to any applicable legal or regulatory requirement; and (iii) claims arising under consumer protection, privacy, or similar legislation."]}, {"heading": "11. Legal compliance", "paragraphs": ["You represent and warrant that You are not located in a country that is subject to a US Government embargo, or that has been designated by the US Government as a \"terrorist supporting\" country; and that You are not listed on any US Government list of prohibited or restricted parties."]}, {"heading": "12. Contact information", "paragraphs": ["For general inquiries, complaints, questions or claims concerning the Licensed Application, please email support@literaryworm.com."]}, {"heading": "13. Termination", "paragraphs": ["The license is valid until terminated by LiteraryWorm or by You. You can end it at any time by deleting your account from Account. Your rights under this license will terminate automatically and without notice from LiteraryWorm if You fail to adhere to any term(s) of this license. Upon License termination, You shall stop all use of the Licensed Application, and remove it and any books saved for offline reading from Your Devices."]}, {"heading": "14. Third-party terms of agreements", "paragraphs": ["LiteraryWorm represents and warrants that LiteraryWorm will comply with applicable third-party terms of agreement when using the Licensed Application, including those of the services it relies on: Supabase, Vercel, Anthropic, Google Books, the Internet Archive, LibriVox and Project Gutenberg."]}, {"heading": "15. Intellectual property rights", "paragraphs": ["LiteraryWorm and the End-User acknowledge that, in the event of any third-party claim that the Licensed Application or the End-User's possession and use of that Licensed Application infringes on the third party's intellectual property rights, LiteraryWorm will be solely responsible for the investigation, defense, settlement, and discharge of any such intellectual property infringement claims. Who owns the books and the app is set out in the Terms of Service."]}, {"heading": "16. Applicable law", "paragraphs": ["This License Agreement is governed by the laws of the State of Illinois excluding its conflicts of law rules."]}, {"heading": "17. Miscellaneous", "paragraphs": ["17.1 If any of the terms of this agreement should be or become invalid, the validity of the remaining provisions shall not be affected. Invalid terms will be replaced by valid ones formulated in a way that will achieve the primary purpose.", "17.2 Collateral agreements, changes and amendments are only valid if laid down in writing. The preceding clause can only be waived in writing."]}]$lw$::jsonb),
  ($lw$acceptable-use$lw$, 7, $lw$Acceptable Use Policy$lw$, $lw$This Acceptable Use Policy ("Policy") is part of our Terms of Service ("Legal Terms") and should therefore be read alongside our main Legal Terms: https://www.literaryworm.com/legal/terms. It sets out what you may and may not do on LiteraryWorm, what you may post, how to use our AI features responsibly, and how to report anything that breaks it.$lw$, $lw$[{"heading": "Agreement to this policy", "paragraphs": ["When you use the AI-powered services provided by LiteraryWorm (\"AI Products\"), you warrant that you will comply with this document, our Legal Terms and all applicable laws and regulations governing AI. Our AI Products are the book summaries and Ask the book, which are written by Claude, an AI model made by Anthropic, and labelled as written by AI. Your usage of our AI Products signifies your agreement to engage with our platform in a lawful, ethical, and responsible manner that respects the rights and dignity of all individuals. If you do not agree with these Legal Terms, please refrain from using our Services. Your continued use of our Services implies acceptance of these Legal Terms.", "Please carefully review this Policy which applies to any and all:", "(a) uses of our Services (as defined in \"Legal Terms\");", "(b) forms, materials, consent tools, comments, posts, and all other content available on the Services (\"Content\");", "(c) material which you contribute to the Services, including any upload, post, reading log, rating, book club post, shared list or comment (\"Contribution\");", "(d) responsible implementation and management of AI Products within our Services."]}, {"heading": "Who we are", "paragraphs": ["We are LiteraryWorm (\"Company,\" \"we,\" \"us,\" or \"our\"). We operate the website https://www.literaryworm.com (the \"Site\"), as well as any other related products and services that refer or link to this Policy (collectively, the \"Services\")."]}, {"heading": "Use of the Services", "paragraphs": ["When you use the Services, you warrant that you will comply with this Policy and with all applicable laws.", "You also acknowledge that you may not:", "1. Systematically retrieve data or other content from the Services to create or compile, directly or indirectly, a collection, compilation, database, or directory without written permission from us.", "2. Make any unauthorized use of the Services, including collecting display names and/or email addresses of users by electronic or other means for the purpose of sending unsolicited email, or creating user accounts by automated means or under false pretenses.", "3. Circumvent, disable, or otherwise interfere with security-related features of the Services, including features that prevent or restrict the use or copying of any Content or enforce limitations on the use of the Services and/or the Content contained therein, such as profile PINs, daily reading limits and age ratings.", "4. Engage in unauthorized framing of or linking to the Services.", "5. Trick, defraud, or mislead us and other users, especially in any attempt to learn sensitive account information such as user passwords.", "6. Make improper use of our Services, including our support services, or submit false reports of abuse or misconduct.", "7. Engage in any automated use of the Services, such as using scripts to send comments or messages, or using any data mining, robots, or similar data gathering and extraction tools.", "8. Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services.", "9. Attempt to impersonate another user or person or use the display name of another user.", "10. Use any information obtained from the Services in order to harass, abuse, or harm another person.", "11. Use the Services as part of any effort to compete with us or otherwise use the Services and/or the Content for any revenue-generating endeavor or commercial enterprise.", "12. Decipher, decompile, disassemble, or reverse engineer any of the software comprising or in any way making up a part of the Services, except as expressly permitted by applicable law.", "13. Attempt to bypass any measures of the Services designed to prevent or restrict access to the Services, or any portion of the Services.", "14. Harass, annoy, intimidate, or threaten any of our employees or agents engaged in providing any portion of the Services to you.", "15. Delete the copyright or other proprietary rights notice from any Content.", "16. Copy or adapt the Services' software, including but not limited to HTML, JavaScript, or other code.", "17. Upload or transmit (or attempt to upload or to transmit) viruses, Trojan horses, or other material, including excessive use of capital letters and spamming (continuous posting of repetitive text), that interferes with any party's uninterrupted use and enjoyment of the Services or modifies, impairs, disrupts, alters, or interferes with the use, features, functions, operation, or maintenance of the Services.", "18. Upload or transmit (or attempt to upload or to transmit) any material that acts as a passive or active information collection or transmission mechanism, including without limitation, clear graphics interchange formats (\"gifs\"), 1×1 pixels, web bugs, cookies, or other similar devices (sometimes referred to as \"spyware\" or \"passive collection mechanisms\" or \"pcms\").", "19. Except as may be the result of standard search engine or Internet browser usage, or the Services' own Read offline feature, use, launch, develop, or distribute any automated system, including without limitation, any spider, robot, cheat utility, scraper, or offline reader that accesses the Services, or use or launch any unauthorized script or other software.", "20. Disparage, tarnish, or otherwise harm, in our opinion, us and/or the Services.", "21. Use the Services in a manner inconsistent with any applicable laws or regulations.", "22. Use a buying agent or purchasing agent to make purchases on the Services.", "23. Sell or otherwise transfer your account or a profile."]}, {"heading": "Subscriptions", "paragraphs": ["If you subscribe to our Services, you understand, acknowledge, and agree that you may not, except if expressly permitted:", "1. Engage in any use, including modification, copying, redistribution, publication, display, performance, or retransmission, of any portions of any Services, other than as expressly permitted by this Policy, without the prior written consent of LiteraryWorm, which consent LiteraryWorm may grant or refuse in its sole and absolute discretion.", "2. Reconstruct or attempt to discover any source code or algorithms of the Services, or any portion thereof, by any means whatsoever. Being able to see source code we publish doesn't give you a license to use it.", "3. Provide, or otherwise make available, the Services to any third party, other than the people in your household who use the profiles on your account.", "4. Intercept any data not intended for you.", "5. Damage, reveal, or alter any user's data, or any other hardware, software, or information relating to another person or entity."]}, {"heading": "AI Products", "paragraphs": ["When you use the AI Products provided by LiteraryWorm, you warrant that you will not:", "1. Try to make the AI Products produce content that this Policy forbids, or that breaks Anthropic's usage policies.", "2. Deploy AI techniques that utilize subliminal, manipulative, or deceptive methods designed to distort behavior and impair informed decision-making, particularly when such actions cause significant harm to individuals.", "3. Exploit vulnerabilities related to age, disability, or socio-economic circumstances through AI in a way that distorts behavior or decision-making, especially if this results in significant harm to the individual.", "4. Use AI systems for biometric categorization that infer sensitive attributes such as race, political opinions, trade union membership, religious or philosophical beliefs, sex life, or sexual orientation, except in limited cases, such as labeling or filtering lawfully acquired datasets, or specific law enforcement activities.", "5. Implement AI-based social scoring systems that evaluate or classify individuals or groups based on their social behavior or personal traits in a manner that causes harm, discrimination, or unfair treatment.", "6. Assess the risk of an individual committing criminal offenses based solely on profiling, personality traits, or other non-behavioral factors, except in narrowly defined circumstances where legal safeguards are in place.", "7. Compile facial recognition databases through untargeted scraping of facial images from the internet, social media, or CCTV footage, unless it is part of a legally compliant and narrowly defined purpose.", "8. Use AI to infer emotions in sensitive environments such as workplaces, educational institutions, or any other context where such analysis could lead to discrimination, unfair treatment, or privacy violations.", "9. Engage in real-time remote biometric identification in public places for law enforcement purposes, except in specific situations where there are strong legal justifications and oversight mechanisms."]}, {"heading": "Artificial intelligence", "paragraphs": ["We recognize the significant impact AI can have on our users and society, and we are dedicated to ensuring that our AI Products are designed and operated in a manner that aligns with comprehensive ethical standards. We aim to use AI to enhance user experiences while upholding fairness, transparency, and accountability principles. That's why everything our AI Products write is labelled as written by AI, and why Ask the book is only given the text up to your place in the book.", "This Policy applies to all AI-powered features, services, and systems in our Services. It governs the development, deployment, and use of AI technologies to protect users' rights and maintain transparency in all AI operations. This Policy applies to all stakeholders, including employees, third-party vendors, and partners who contribute to or interact with our AI Products.", "Enforcement. Any misuse of our AI Products or failure to adhere to the standards outlined in this Policy will result in appropriate actions to ensure the integrity of our platform and the protection of our users. The specific consequences for misuse of AI may vary depending on the nature and severity of the violation and the user's history with our Services.", "Violations may include, but are not limited to:", "1. Engaging the AI Products in ways that violate user privacy, manipulate data, disregard ethical guidelines, or are against AI service providers' terms of use (for our AI Products, Anthropic's).", "2. Deploying AI in a manner that introduces or causes bias, leading to unfair treatment of users or groups.", "3. Improper handling, storage, or use of data by AI Products, leading to breaches of user trust and legal compliance.", "4. Using AI in a way that compromises the privacy and security of our systems, data, or users.", "Depending on the violation, LiteraryWorm may take one or more of the following actions:", "Warnings: The responsible party may receive a formal warning and be required to cease violating practices.", "Temporary Suspension: In cases of repeated or more severe violations, the responsible individual's access to AI Products or certain features of our platform may be temporarily suspended while the issue is investigated.", "Termination of Access: Serious violations, particularly those that result in harm to users or breach privacy or other regulations, may lead to the permanent termination of access to our AI Products and Services.", "Legal Action: In cases where the misuse of AI leads to significant harm, data breaches, or legal violations, we may pursue legal action against the party responsible. This could include reporting the incident to law enforcement or regulatory bodies.", "Public Disclosure: For incidents that impact public trust or involve severe ethical breaches, we reserve the right to publicly disclose the violation and the actions taken in response to maintain transparency and accountability.", "Commitment to Responsible AI. In addition to the consequences outlined above, we are deeply committed to repairing any harm caused by the misuse of AI. This commitment is a testament to our dedication to our users and our responsibility as a company. We will correct biased outcomes and implement additional safeguards to prevent future violations.", "At LiteraryWorm, we are committed to the ongoing refinement and enhancement of our Policy. As technology evolves and regulatory environments shift, we recognize the importance of keeping our policies up to date to ensure that they remain relevant, effective, and aligned with best practices in AI ethics. We will regularly review and update our Policy to reflect technological advancements and legal changes in local, national, and international regulations related to AI. Our Policy will be updated as needed to comply with new laws and guidelines, ensuring that our practices remain legally sound and socially responsible."]}, {"heading": "Contributions", "paragraphs": ["In this Policy, the term \"Contributions\" means: any data, information, text, messages or other materials that you post, share, upload, submit, or otherwise provide in any manner on or through the Services, such as reading logs, ratings, book club posts, list names and descriptions, notes and highlights, and books you upload; or any other content, materials, or data you provide to LiteraryWorm or use with the Services.", "Some areas of the Services allow users to upload, transmit, or post Contributions. We may but are under no obligation to review or moderate the Contributions made on the Services, and we expressly exclude our liability for any loss or damage resulting from any of our users' breach of this Policy. Please report any Contribution that you believe breaches this Policy; however, we will determine, in our sole discretion, whether a Contribution is indeed in breach of this Policy.", "You warrant that:", "1. you are the creator and owner of or have the necessary licenses, rights, consents, releases, and permissions to use and to authorize us, the Services, and other users of the Services to use your Contributions in any manner contemplated by the Services and this Policy;", "2. all your Contributions comply with applicable laws and are original and true (if they represent your opinion or facts);", "3. the creation, distribution, transmission, public display, or performance, and the accessing, downloading, or copying of your Contributions do not and will not infringe the proprietary rights, including but not limited to the copyright, patent, trademark, trade secret, or moral rights of any third party; and", "4. you have the verifiable consent, release, and/or permission of each and every identifiable individual person in your Contributions to use the name or likeness of each and every such identifiable individual person to enable inclusion and use of your Contributions in any manner contemplated by the Services and this Policy.", "You also agree that you will not post, transmit, or upload any (or any part of a) Contribution that:", "1. is in breach of applicable laws, regulation, court order, contractual obligation, this Policy, our Legal Terms, a legal duty, or that promotes or facilitates fraud or illegal activities;", "2. is defamatory, obscene, offensive, hateful, insulting, intimidating, bullying, abusive, or threatening, to any person or group;", "3. is false, inaccurate, or misleading;", "4. includes child sexual abuse material, or violates any applicable law intended to protect minors;", "5. contains any material that solicits personal information from anyone under the age of 18 or exploits people under the age of 18 in a sexual or violent manner;", "6. promotes violence, advocates the violent overthrow of any government, or incites, encourages, or threatens physical harm against another;", "7. is obscene, lewd, lascivious, filthy, violent, harassing, libelous, slanderous, contains sexually explicit material, or is otherwise objectionable (as determined by us);", "8. is discriminatory based on race, sex, religion, nationality, disability, sexual orientation, or age;", "9. bullies, intimidates, humiliates, or insults any person;", "10. promotes, facilitates, or assists anyone in promoting and facilitating acts of terrorism;", "11. infringes, or assists anyone in infringing, a third party's intellectual property rights or publicity or privacy rights;", "12. is deceitful, misrepresents your identity or affiliation with any person and/or misleads anyone as to your relationship with us or implies that the Contribution was made by someone else than you;", "13. contains unsolicited or unauthorized advertising, promotional materials, pyramid schemes, chain letters, spam, mass mailings, or other forms of solicitation that has been \"paid for,\" whether with monetary compensation or in kind; or", "14. misrepresents your identity or who the Contribution is from."]}, {"heading": "Reviews and ratings", "paragraphs": ["When your Contribution is a review or rating of a book, such as a rating or a reading log, you also agree that:", "1. you have firsthand experience with the book being reviewed;", "2. your Contribution is true to your experience;", "3. you are not affiliated with competitors if posting negative reviews (or linked in any way to, e.g., by being the author or publisher of, a book if posting positive reviews);", "4. you cannot make or offer any conclusions as to the legality of conduct;", "5. you cannot post any false or misleading statements; and", "6. you do not and will not organize a campaign encouraging others to post reviews, whether positive or negative."]}, {"heading": "Reporting a breach of this policy", "paragraphs": ["We may but are under no obligation to review or moderate the Contributions made on the Services and we expressly exclude our liability for any loss or damage resulting from any of our users' breach of this Policy.", "If you consider that any Service, Content, or Contribution breaches this Policy, please email us at report@literaryworm.com to let us know which Service, Content, or Contribution is in breach of this Policy and why.", "If you consider that any Service, Content, or Contribution infringes any third-party intellectual property rights, please email us at report@literaryworm.com. For a formal notice under the Digital Millennium Copyright Act, follow the steps on our Copyright/DMCA page.", "You can also send detailed feedback on your interactions with our AI Products by emailing report@literaryworm.com. Please include specific details about the AI interaction, such as the book, the context, the nature of the concern, and any relevant screenshots or documentation.", "We will reasonably determine whether a Service, Content, or Contribution breaches this Policy."]}, {"heading": "Consequences of breaching this policy", "paragraphs": ["The consequences for violating our Policy will vary depending on the severity of the breach and the user's history on the Services, by way of example:", "We may, in some cases, give you a warning and/or remove the infringing Contribution, however, if your breach is serious or if you continue to breach our Legal Terms and this Policy, we have the right to suspend or terminate your access to and use of our Services and, if applicable, disable your account. We may also notify law enforcement or issue legal proceedings against you when we believe that there is a genuine risk to an individual or a threat to public safety.", "We exclude our liability for all action we may take in response to any of your breaches of this Policy."]}, {"heading": "Complaints and removal of legitimate content", "paragraphs": ["If you consider that some Content or Contribution has been mistakenly removed or blocked from the Services, please email us at report@literaryworm.com and we will promptly review our decision to remove such Content or Contribution. The Content or Contribution may stay \"down\" whilst we conduct the review process. If it was removed after a copyright notice, you can also send a counter-notice, as our Copyright/DMCA page explains."]}, {"heading": "Disclaimer", "paragraphs": ["LiteraryWorm is under no obligation to monitor users' activities, and we disclaim any responsibility for any user's misuse of the Services. LiteraryWorm has no responsibility for any user or other Content or Contribution created, maintained, stored, transmitted, or accessible on or through the Services, and is not obligated to monitor or exercise any editorial control over such material. If LiteraryWorm becomes aware that any such Content or Contribution violates this Policy, LiteraryWorm may, in addition to removing such Content or Contribution and blocking your account, report such breach to the police or appropriate regulatory authority. Unless otherwise stated in this Policy, LiteraryWorm disclaims any obligation to any person who has not entered into an agreement with LiteraryWorm for the use of the Services."]}, {"heading": "How can you contact us about this policy?", "paragraphs": ["If you have any further questions or comments or wish to report any problematic Content or Contribution, you may contact us by email: report@literaryworm.com."]}]$lw$::jsonb),
  ($lw$copyright$lw$, 8, $lw$Copyright/DMCA$lw$, $lw$How LiteraryWorm respects copyright, which works are in the public domain, and how a rights holder can report content they believe infringes, under the Digital Millennium Copyright Act (DMCA).$lw$, $lw$[{"heading": "Our books and their licences", "paragraphs": ["Public-domain titles use texts from Project Gutenberg and recordings from LibriVox, which LibriVox volunteers release into the public domain. These works are in the public domain in the United States, where LiteraryWorm operates. Our copies leave out Project Gutenberg's own header, footer and licence text.", "Other titles show sample pages written for LiteraryWorm, not the published books, and book details and covers come from Google Books under Google's terms.", "If you believe any of this is wrong, for example that a work isn't in the public domain, tell us using the steps below and we'll look into it promptly."]}, {"heading": "What people post or upload", "paragraphs": ["Reading logs, club posts and shared lists are written by members, who keep their rights in them. Books members upload are private to their own profile and aren't shown to anyone else; members must have the right to read them that way (see the Terms of Service)."]}, {"heading": "Reporting content", "paragraphs": ["Users can report user-generated content and copyright infringement, and get information about the Acceptable Use Policy, by emailing report@literaryworm.com."]}, {"heading": "Reporting infringement", "paragraphs": ["If you believe something on LiteraryWorm infringes your copyright, send our designated agent a written notice that includes: your physical or electronic signature; the work you believe is infringed; the material on LiteraryWorm you want removed and where it is (a link helps); your name, address, phone number and email; a statement that you believe in good faith the use isn't authorised by the copyright owner, its agent or the law; and a statement, under penalty of perjury, that the notice is accurate and that you are, or are authorised to act for, the owner.", "Our designated agent's name, postal address, phone number and email, as registered with the U.S. Copyright Office, will be listed here before launch.", "We remove or disable access to the material, tell the member who posted it, and keep a record of the notice."]}, {"heading": "Counter-notices", "paragraphs": ["If your content was removed and you believe that was a mistake or that you had the right to post it, you may send a counter-notice with: your signature; what was removed and where it was; a statement, under penalty of perjury, that you believe in good faith it was removed by mistake or misidentification; your name, address and phone number; and your consent to the jurisdiction of the federal court for your address (or, outside the United States, any district where LiteraryWorm may be found) and to accept service from the person who sent the notice.", "We forward it to the person who sent the notice and may restore the content in 10 to 14 business days unless they tell us they've filed a court action."]}, {"heading": "Repeat infringers and false claims", "paragraphs": ["We close the accounts of members who repeatedly infringe copyright.", "Knowingly misrepresenting that material infringes, or that it was removed by mistake, can make you liable for damages under the DMCA, so please be sure before you send a notice or counter-notice."]}]$lw$::jsonb),
  ($lw$disclaimer$lw$, 9, $lw$Disclaimer$lw$, $lw$The information provided by LiteraryWorm ("we," "us," or "our") on https://www.literaryworm.com (the "Site") is for general informational purposes only. This page explains what we can and can't promise about it, and about the other websites the Site links to.$lw$, $lw$[{"heading": "Website disclaimer", "paragraphs": ["All information on the Site is provided in good faith, however we make no representation or warranty of any kind, express or implied, regarding the accuracy, adequacy, validity, reliability, availability, or completeness of any information on the Site. This includes book details and covers from Google Books, and summaries and answers written by AI, which are labelled as such.", "UNDER NO CIRCUMSTANCE SHALL WE HAVE ANY LIABILITY TO YOU FOR ANY LOSS OR DAMAGE OF ANY KIND INCURRED AS A RESULT OF THE USE OF THE SITE OR RELIANCE ON ANY INFORMATION PROVIDED ON THE SITE. YOUR USE OF THE SITE AND YOUR RELIANCE ON ANY INFORMATION ON THE SITE IS SOLELY AT YOUR OWN RISK."]}, {"heading": "External links disclaimer", "paragraphs": ["The Site may contain (or you may be sent through the Site) links to other websites or content belonging to or originating from third parties, such as Google Books, the Internet Archive, LibriVox and Project Gutenberg. The Site doesn't show advertising. Such external links are not investigated, monitored, or checked for accuracy, adequacy, validity, reliability, availability, or completeness by us.", "WE DO NOT WARRANT, ENDORSE, GUARANTEE, OR ASSUME RESPONSIBILITY FOR THE ACCURACY OR RELIABILITY OF ANY INFORMATION OFFERED BY THIRD-PARTY WEBSITES LINKED THROUGH THE SITE. WE WILL NOT BE A PARTY TO OR IN ANY WAY BE RESPONSIBLE FOR MONITORING ANY TRANSACTION BETWEEN YOU AND THIRD-PARTY PROVIDERS OF PRODUCTS OR SERVICES."]}, {"heading": "Testimonials disclaimer", "paragraphs": ["The Site doesn't show testimonials at the moment. Reading logs and book club posts are written by members and belong to them; they don't reflect our views and opinions.", "If we add testimonials by users of our products and/or services, they will reflect the real-life experiences and opinions of such users. However, the experiences are personal to those particular users, and may not necessarily be representative of all users of our products and/or services. We do not claim, and you should not assume, that all users will have the same experiences. YOUR INDIVIDUAL RESULTS MAY VARY.", "Testimonials will be reviewed by us before being posted, and will appear on the Site verbatim as given by the users, except for the correction of grammar or typing errors. Some testimonials may be shortened for the sake of brevity where the full testimonial contained extraneous information not relevant to the general public.", "The views and opinions contained in testimonials belong solely to the individual user and do not reflect our views and opinions. Users will not be paid or otherwise compensated for their testimonials, and we'll say so if anyone who gives one is connected to us."]}]$lw$::jsonb),
  ($lw$help$lw$, 10, $lw$Help$lw$, $lw$Answers to common questions about reading, listening, your library and your account, and how to report a problem.$lw$, $lw$[{"heading": "Where do the books come from?", "paragraphs": ["LiteraryWorm uses the Google Books API to show book details and covers when you browse and search, so you can find almost any book, save it to your library and write about it.", "The books you can read and listen to in full are public-domain classics: texts from Project Gutenberg and recordings from LibriVox. Other LiteraryWorm titles show sample pages."]}, {"heading": "Can I read my own books?", "paragraphs": ["Yes. In My Library → Uploads, add an EPUB you own that has no DRM. For example, buy a book that the publisher sells DRM-free on Google Play Books, download its EPUB from your Google Play Books library, then upload it to LiteraryWorm. Many publishers and stores sell DRM-free books, and public-domain EPUBs are free from Project Gutenberg and Standard Ebooks.", "Your upload opens in the reader with your place, bookmarks and highlights, and once you've opened it on a device, it keeps working there if your connection drops. Books with DRM can't be uploaded, and removing DRM to upload a book isn't allowed (see the Terms of Service)."]}, {"heading": "Reading and listening", "paragraphs": ["Open a book from its page with Read or Listen. Your place is shared between the two and across your devices. The mini-player keeps a book playing while you browse, and its controls also work from your lock screen and headphones.", "To read or listen without a connection, choose Read offline on a public-domain book's page."]}, {"heading": "Your account and household", "paragraphs": ["Each person at home can have their own profile, with its own library and recommendations. Lock a profile with a PIN, set daily limits for younger readers, and change your plan, password or emails in Account. You can cancel or pause online at any time."]}, {"heading": "Report a problem", "paragraphs": ["Tell us what you were doing, the page you were on, and your device and browser. Contact details for support will be published here before launch; until then, LiteraryWorm is a demonstration."]}]$lw$::jsonb),
  ($lw$status$lw$, 11, $lw$Status$lw$, $lw$All systems are working normally.$lw$, $lw$[{"heading": "Services", "paragraphs": ["Website and app: working normally.", "Accounts, libraries and reading progress: working normally.", "Book search and details (Google Books): working normally.", "Audiobook recordings (Internet Archive): working normally.", "Summaries and Ask the book (AI): working normally."]}, {"heading": "If something isn't working", "paragraphs": ["Your reading progress is saved on your device first and sent when the connection returns, so you won't lose your place. Books saved for offline keep working without a connection."]}]$lw$::jsonb)
